programs.sol:
"""A written-nine detector with a small background response.

Recognize 9, English nine-related number words, Chinese forms containing
nine, and September. Predict a generally smaller digit response inside a
number, after another nine, or in hex escapes and HTML character codes.
Document-initial 9 has its own lower response. Also recognize fullwidth,
Persian, superscript and subscript nines, and the thin typographic space.
These are fitted response sizes, not a calculation of numerical value.
Small, unrelated token-specific responses are intentionally left out.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, '')
    _, previous, digits, before_number = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()

    value = 0.001
    if word == '9':
        if previous == '':
            value = 0.66
        elif previous == '9':
            value = 0.95
        elif digits > 1:
            value = 1.04
        elif digits:
            value = 1.10
        elif previous.strip().isalpha():
            value = 1.44
        elif previous in ('.', ',', '=', ' +'):
            value = 1.13
        elif previous.isspace():
            value = 1.25
        else:
            value = 1.31
        if previous == '\\x':
            value = 0.84
        elif digits and before_number in ('\\x', '&#'):
            value = 0.71
    elif lower in ('nine', '-nine'):
        value = 1.28 if token.startswith((' ', '-')) else 0.90
    elif lower == 'ninth':
        value = 1.38 if word[0].isupper() else 1.10
    elif lower == 'ninety':
        value = 0.94
    elif lower in ('nineteen', 'nineteenth'):
        value = 0.42
    elif lower == 'september':
        value = 0.67 if token.startswith(' ') else 0.55
    elif lower == 'sep':
        value = 0.21
    elif lower == 'sept':
        value = 0.08
    elif word == '九':
        value = 1.70
    elif word == '第九':
        value = 1.50
    elif '十九' in word:
        value = 1.16
    elif '九' in word:
        value = 0.75

    # A byte fragment may complete a Unicode character only when decoded
    # together with the preceding bytes. Read the full prefix only then.
    character = token[-1:]
    if '\ufffd' in token and previous:
        character = prefix.text_prefixes[-1][-1:]
    if character == '９':
        value = 0.97
    elif character == '۹':
        value = 2.08
    elif character == '⁹':
        value = 1.60
    elif character == '₉':
        value = 1.26
    elif character == '\u2009':
        value = 0.78

    if token.isdigit():
        if not digits:
            before_number = previous
        digits += len(token)
    else:
        digits = 0
    return (doc, token, digits, before_number), value

programs.haiku:
"""Digit-nine detector for layers.0.mlp.down_proj, component 1024.

What it does: the component's activation is close to zero almost everywhere, and jumps
up on the current token when that token is the number nine, written as a digit (9, ９),
as a number word (nine, ninth, ninety, 九, 第九), or as "September" / "Sep" (the ninth
month). Each has its own typical strength; everything else is predicted as 0.

It looks only at the token being read now (prefix.token_strings[-1]), so it needs no carry.
"""

READS = ()

DIGIT_NINE = {"9", "９"}
NINE_WORDS = {"nine", "ninth", "ninety", "nineteen", "九", "第九"}
SEPTEMBER = {"september", "sep"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in DIGIT_NINE:
        return carry, 1.1
    if token in NINE_WORDS:
        return carry, 1.3
    if token in SEPTEMBER:
        return carry, 0.65
    return carry, 0.0

programs.sol:
"""Approximate several lexical and orthographic responses of this component.

Chinese basis/source expressions and some English source phrases produce
negative values. Math-font names and private-use symbol characters produce
positive values. Letters after short-u vowel signs in four South Asian
scripts form another positive mode. These rules capture distinctive peaks,
not the many small responses on ordinary tokens; unrecognized tokens get 0.
Only two prior tokens and a vowel/byte-fragment cue are remembered, with
context reset whenever the document label changes.
"""
import unicodedata

READS = ()

# Words for basing, reporting, consulting, or following information.
SOURCE_WORDS = {
    '根据': -1.62, '根據': -1.62,
    '依据': -1.90, '依據': -1.47,
    '可以根据': -1.21, '可根据': -1.63,
    '凭': -1.26, '憑': -1.20,
    '凭借': -0.66, '憑藉': -0.66, '凭证': -0.80,
    '据': -0.52, '據': -0.43, '据统计': -0.40,
    '结合': -0.45, '結合': -0.38, '配合': -0.24,
    '参考': -0.33, '參考': -0.31, '参照': -0.36,
    '參照': -0.36, '依照': -0.65, '按照': -0.24,
    '遵循': -0.21, '基于': -0.17, '基於': -0.17,
}
MATH_FONTS = {'cal': 0.43, 'bb': 0.40, 'bf': 0.27}
# Short-u vowel signs, with script-specific response strengths.
SHORT_U = {'ு': 1.80, 'ు': 1.80, 'ु': 1.00, 'ุ': 0.35}


def consonant(character):
    code = ord(character)
    return ((0x915 <= code <= 0x939 or 0xB95 <= code <= 0xBB9
             or 0xC15 <= code <= 0xC39 or 0xE01 <= code <= 0xE2E)
            and unicodedata.category(character).startswith('L'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    if not same_document:
        previous, before_previous = '', ''
        last_character, pending_u = '', None
    else:
        _, previous, before_previous, last_character, pending_u = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    character = token[-1:] or ' '
    if same_document and '\ufffd' in token:
        character = prefix.text_prefixes[-1][-1:] or ' '

    last_word = previous.strip()
    older_word = before_previous.strip()
    value = SOURCE_WORDS.get(word, 0.0)
    if word in ('据', '據') and previous.endswith(('根', '依')):
        value = -1.90
    elif word.lower() in ('evidence', 'evid'):
        value = -0.20 if word[:1].isupper() else -0.24
    elif word.lower() in ('basis', 'reference'):
        value = -0.07
    elif previous.endswith('preced') and word in (
            'ent', 'ents', 'ente', 'enti', 'entes'):
        # English and Romance-language forms of 'precedent/preceding'.
        value = -0.50 if word == 'ente' else -0.33
    elif word in MATH_FONTS and previous.endswith('math'):
        value = MATH_FONTS[word]

    # Completing English source/basis phrases. Capitalized introductions
    # have a somewhat stronger response than the same words in mid-sentence.
    if token.startswith(' '):
        capitalized = last_word[:1].isupper()
        if word == 'on' and last_word.lower() == 'based':
            value = -0.12 if capitalized else -0.07
        elif word == 'to' and last_word.lower() == 'according':
            value = -0.11 if capitalized else -0.06
        elif word == 'the':
            if last_word.lower() == 'from':
                value = -0.15 if capitalized else -0.07
            elif last_word.lower() in ('use', 'using'):
                value = -0.23 if capitalized else -0.13
            elif last_word == 'on' and older_word.lower() == 'based':
                value = -0.34 if older_word[:1].isupper() else -0.18
        elif word == 'from' and last_word.lower() in ('evidence', 'inferred'):
            value = -0.23

    # Legacy private-use symbol-font characters seen in mathematical text.
    if 0xF061 <= ord(character) <= 0xF079:
        value = 1.00

    after_u = SHORT_U.get(last_character, 0.0)
    new_pending = None
    if token == '\ufffd' and after_u and character == '\ufffd':
        value = max(0.0, after_u - 0.10)
        new_pending = last_character
    elif after_u and token and consonant(token[0]):
        value = after_u
    elif pending_u and (consonant(character) or character == 'ం'):
        value = 0.78 * SHORT_U[pending_u]
    return (doc, token, previous, character, new_pending), float(value)

programs.luna:
"""Recognize Chinese phrases that introduce what a claim is based on."""

READS = ()

# These forms mean “according to,” “based on,” or “by means of.”
BASIS_CUES = {"根据", "根據", "可根据", "依據", "依据", "凭", "憑"}


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] in BASIS_CUES:
        return None, -1.35
    return None, 0.0

programs.haiku:
"""Token detector for "featured / starred / key-priority" words.

Layer-0 MLP component layers.0.mlp.down_proj:1026 is almost purely a word detector.
Its strongest responses are negative and fire on words that mean "singled out as a
highlight": the word "feature" and its forms (featured, featuring, features), star and
celebrity words, and the Chinese words for "key focus" and "star" (重点, 明星).
Everywhere else it is near zero, with a long diffuse tail of small values on other
words that this program does not capture.

The program is a lookup from the newest token to a rough mean activation for its word
class. It has no state: each position depends only on its own token.
"""

READS = ()

FEATURE_WORDS = {"feature","features", "featured", "featuring", "_feature"}
STAR_WORDS = {"star", "stars", "starring", "starred", "celebrity", "celebrities"}
KEY_WORDS = {"重点", "重點", "明星", "主打"}  # "key focus", "star", "flagship"
PROMINENT_WORDS = {
    "favorite", "favourite", "flagship", "headline", "spotlight", "leading",
    "selected", "signature", "mainstream", "debut", "top", "main", "core",
    "priority", "priorities", "keynote", "premiere", "highlight", "showcase",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in FEATURE_WORDS:
        value = -0.28
    elif word in STAR_WORDS:
        value = -0.2
    elif word in KEY_WORDS:
        value = -0.67
    elif word in PROMINENT_WORDS:
        value = -0.08
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Mark words about a feature or a prominent, featured subject.

The component is usually quiet. It gives its strongest negative response to
"featured" and the Chinese words for a star or key focus; related forms of
"feature" and "starring" get a smaller pulse.
"""

READS = ()

PROMINENCE_WORDS = {"明星", "重点", "重點"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    lower = word.lower()
    if word in PROMINENCE_WORDS:
        value = -0.86
    elif lower.startswith("featured"):
        value = -0.62
    elif lower.startswith("feature"):
        value = -0.38
    elif lower == "starring":
        value = -0.40
    else:
        value = 0.0
    return None, value

programs.sol:
"""Script onsets, strongest at the beginning of a katakana run.

Katakana often spells Japanese loanwords and names. A short token starting
such a run gets a large negative value; continuing kana suppresses it.
Length, small kana, preceding hiragana, and spaces adjust that value.
Weaker rules cover short Thai and Korean tokens, Arabic article prefixes,
Chinese foreign-name characters, and split UTF-8 characters. Document
boundaries reset the state. This is a script heuristic, not a word parser.
"""
import unicodedata

READS = ()
SMALL_KANA = frozenset('ァィゥェォッャュョヮヵヶ')
# UTF-8 fragments: space + E3 82 spans hiragana/early katakana;
# space + E3 83 spans later katakana. These are script ranges, not word IDs.
SPACED_HIRAGANA_KATAKANA_LEAD = 17587
SPACED_KATAKANA_LEAD = 20711
NAME_CHARACTERS = frozenset('阿艾埃奥巴贝伯博布迪弗菲哈赫霍卡凯洛穆帕佩萨塞泰沃伊尤')


def is_katakana(c):
    return '\u30a1' <= c <= '\u30fa' or c == 'ー'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    text = raw.strip()
    if any('\uff66' <= c <= '\uff9d' for c in text):
        text = unicodedata.normalize('NFKC', text)
    fresh = carry is None or carry[0] != doc
    previous = '' if fresh else carry[1]
    previous_length = 0 if fresh else carry[2]
    if not fresh and '�' in previous:
        previous = prefix.text_prefixes[-2][-1:]
        previous_length = int(bool(previous) and is_katakana(previous[-1]))
    kana = sum(is_katakana(c) for c in text)
    value = -0.003
    if fresh:
        value = 0.0
    elif kana and is_katakana(text[0]):
        if text[0] in SMALL_KANA:
            value = -0.2 if kana == 1 else 0.07
        elif previous_length:
            if previous_length == 1:
                value = -0.26 if kana == 1 else 0.06
            else:
                value = -0.75 / kana ** 0.8
        elif text[0] == 'ー':
            value = -1.5
        elif previous == '�':
            value = -0.5 if kana == 1 else -0.3
        else:
            length = kana - 0.6 * sum(c in SMALL_KANA for c in text)
            value = -4.2 / length ** 0.8
            if previous and '\u3040' <= previous[-1] <= '\u309f':
                value *= 1.15
            if raw.startswith(' '):
                value *= 0.5
    elif prefix.token_ids[-1] == SPACED_HIRAGANA_KATAKANA_LEAD:
        value = -0.85
    elif prefix.token_ids[-1] == SPACED_KATAKANA_LEAD:
        value = -1.5
    elif '�' in text:
        # Decode only at split UTF-8 characters; never inspect later tokens.
        last = prefix.text_prefixes[-1][-1:]
        if last != '�':
            value = -0.85 if is_katakana(last) else -0.08
            if '\u4e00' <= last <= '\u9fff':
                value = 0.0
            elif '\uac00' <= last <= '\ud7af':
                value = -0.18
        elif raw.startswith(' '):
            follows_korean = previous and '\uac00' <= previous[-1] <= '\ud7af'
            value = -0.85 if follows_korean else -0.12
        else:
            japanese = previous and (
                '\u4e00' <= previous[-1] <= '\u9fff'
                or '\u3040' <= previous[-1] <= '\u309f'
                or previous[-1] in '、。「」'
            )
            value = -0.65 if japanese else -0.16
    elif any('\u0e00' <= c <= '\u0e7f' for c in text):
        n = len(text)
        value = -0.65 / n ** 0.8
        if unicodedata.category(text[0]) == 'Mn':
            value = -0.12 if n == 1 else 0.0
        elif text[0] in 'เแโใไ' and n <= 2:
            value = -1.0
    elif any('\uac00' <= c <= '\ud7af' for c in text):
        n = sum('\uac00' <= c <= '\ud7af' for c in text)
        value = -0.5 / n ** 2 if raw.startswith(' ') else -0.1 / n
    elif any('\u0600' <= c <= '\u06ff' for c in text):
        n = sum('\u0600' <= c <= '\u06ff' for c in text)
        if raw.startswith(' '):
            value = -0.25 if n == 1 else -0.08
            if text.startswith(('ال', 'إل', 'أل')) and n >= 3:
                value = -0.9 * (3.0 / n) ** 1.3
    elif text in NAME_CHARACTERS:
        value = -0.7
    # Only a kana-ending token continues the run.
    previous_kana_length = kana if text and is_katakana(text[-1]) else 0
    return (doc, text[-1:] or ' ', previous_kana_length), float(value)

"""A shallow lexical rule for 'to' and 'that'.

Coordination and result phrases are strong, as are selected motion,
continuation and evidence words. Desire/necessity and method nouns weaken
'to'. Named word classes and ordinary English inflection approximate these
patterns; this is not a parser. Small side rules cover joined spellings,
naming and several non-English complementizers. Other tokens get near zero.
The preceding token is retained in state, reset between documents.
"""
READS = ()


def word_map(groups):
    return {word: value for value, words in groups.values()
            for word in words.split()}


TO = word_map({
    'coordination': (1.14, 'but or'),
    'and': (1.58, 'and'),
    'desire/necessity': (-0.15, 'need want'),
    'attempt/decision': (0.07, 'try attempt decide'),
    'methods/plans': (-0.36,
        'way method approach solution plan decision desire'),
    'relations': (0.08,
        'due according relate respect response reference refer prior access '
        'addition add contribute dedicate'),
    'difficulty/requirements': (0.10,
        'difficult important possible necessary hard easy easier harder '
        'ability expect suppose require impossible'),
    'use': (-0.09, 'use'),
    'comparison': (-0.16, 'compare comparison'),
    'questions': (-0.07, 'how what'),
    'motion/continuation': (0.96,
        'go went come came return move continue seem ready set start'),
    'direction': (1.62, 'lead led turn'),
    'tendency/beginning': (1.75, 'tend begin began'),
    'evidence': (1.41, 'find found show shown known seen'),
    'degree/willingness': (1.15, 'likely enough willing free happy'),
    'having': (0.97, 'have has had'),
    'purpose': (1.12, 'order'),
})
THAT = word_map({
    'result': (2.52, 'so'),
    'degree': (1.51, 'such'),
    'coordination': (1.60, 'and but or'),
    'evidence': (1.19, 'find found show shown known seen'),
    'certainty/noticing': (0.65,
        'know knew ensure sure clear conclude suppose feel note notice see observe'),
    'mention/consideration': (-0.27,
        'mention require remember understand consider'),
    'being': (0.50, 'is are was were be been'),
    'indefinites/fact': (-0.23, 'thing something anything nothing fact'),
    'prepositions': (0.06, 'of for from in at into to about after'),
    'meaning/focus': (0.86,
        'mean meaning follows not only just except then now maybe'),
})


def forms(word):
    """Possible base forms; a candidate is used only if in a named class."""
    yield word
    if word.endswith(('ies', 'ied')):
        yield word[:-3] + 'y'
    if word.endswith('s'):
        yield word[:-1]
        if word.endswith('es'):
            yield word[:-2]
    for ending in ('ed', 'ing'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            yield stem
            yield stem + 'e'
            if len(stem) > 1 and stem[-1] == stem[-2]:
                yield stem[:-1]


def class_value(word, classes):
    for base in forms(word):
        if base in classes:
            return classes[base]
    return None


def predict(token, previous, start):
    word = token.strip()
    prev = previous.strip().lower()
    if word.lower() in {'to', 'that'}:
        is_to = word.lower() == 'to'
        if start:
            return 0.20 if is_to else 0.10
        if word != word.lower():
            return 0.35 if is_to else 0.81
        value = class_value(prev, TO if is_to else THAT)
        if value is not None:
            return value
        if ',' in previous:
            return 0.94 if is_to else 1.00
        if not is_to and any(c in previous for c in '.!?;:'):
            return 0.77
        if is_to and prev.isdigit():
            return 0.67
        if prev.endswith(('tion', 'sion', 'ment')):
            return 0.31 if is_to else 0.06
        if prev.endswith('ly'):
            return 0.68 if is_to else 0.79
        if not is_to and prev.endswith('ed'):
            return 0.42
        if not is_to and prev.endswith('s'):
            return 0.06
        return 0.50 if is_to else 0.28
    if word in {'-to', '_to'}:
        return 0.58
    if word in {'dass', 'daß', 'že'}:
        return 0.61
    if word == 'что':
        return 0.23
    if word == '-called' or (word == 'called' and prev == 'so'):
        return 0.95
    if word == 'called':
        return 0.32
    if word in {'as', 'about'} and prev == 'so':
        return 0.66
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    token = prefix.token_strings[-1]
    return (doc, token), float(predict(token, previous, start))

programs.luna:
"""Predict the strong 'to'/'that' signal, including common two-word phrases."""

import re

READS = ()

TO_PHRASES = {
    "and": 1.55,
    "way": -0.42,
    "have": 0.97,
    "going": 0.87,
    "want": -0.11,
    "used": -0.05,
    "how": -0.04,
}
THAT_PHRASES = {"so": 2.48, "and": 1.66, "such": 1.54}


def previous_word(prefix):
    end = len(prefix.token_strings) - 1
    beginning = max(0, end - 12)
    doc = prefix.document_ids[-1]
    while beginning < end and prefix.document_ids[beginning] != doc:
        beginning += 1
    recent = "".join(prefix.token_strings[beginning:end]).lower()
    match = re.search(r"([a-z]+)[^a-z]*$", recent)
    return match.group(1) if match else ""


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in ("to", "that"):
        return None, 0.0

    previous = previous_word(prefix)
    if word == "that":
        return None, THAT_PHRASES.get(previous, 0.42)
    return None, TO_PHRASES.get(previous, 0.466)

programs.sol:
"""A negative lexical cue for enabling and changing into action.

Recognize normal English inflections of a small set of enabling, activation,
and starting/motion verbs, plus selected Chinese equivalents. Enabling is
stronger than generic motion. 'Turn on/off' is a stronger phrase than 'turn'.
Join split word endings, recover completed Unicode characters, and forget
context at document boundaries. Unrecognized tokens receive zero.
"""
READS = ()


def forms(word, root):
    """The ordinary base, third-person, past, and -ing forms of these verbs."""
    return word in (root, root + 's', root + ('d' if root.endswith('e') else 'ed'),
                    (root[:-1] if root.endswith('e') else root) + 'ing')


def lexical(word, spaced):
    scale = 1.0 if spaced else 0.8
    if forms(word, 'enable') or word == 'enablement':
        return -2.5 * scale
    if forms(word, 'disable'):
        return -1.3 if word == 'disable' else -0.95
    if forms(word, 'activate') or word in ('activation', 'activations'):
        return -0.9 * scale
    for root, value in (('turn', -0.56), ('launch', -0.55), ('trigger', -0.95),
                        ('toggle', -0.8), ('ignite', -0.82), ('embark', -0.9),
                        ('flip', -0.48), ('unlock', -0.48), ('awaken', -0.45),
                        ('initiate', -0.48), ('inspire', -0.5), ('spark', -0.55)):
        if forms(word, root):
            return value
    if word in ('activ', 'inspiration', 'ignition', 'enlightenment', 'enlightened'):
        return -0.6
    # Chinese enabling/start words, with especially strong 启/啟 characters.
    for words, value in (
            (('启',), -6.6), (('啟',), -6.0), (('开启',), -4.4),
            (('開啟',), -3.1), (('启用',), -3.9), (('启发',), -3.0),
            (('启示', '启动'), -2.0),
            (('激活', '触发', '开通'), -1.15),  # Activate, trigger, enable service.
            (('打开', '关闭', '开机'), -0.9),   # Open, close, power on.
            (('展开', '閉', '闭', '唤醒', '开关', '解锁', '引发'), -0.72),
            (('实现', '实现了', '新开'), -0.55)):  # Implement; newly opened.
        if word in words:
            return value
    return -0.58 if word == 'ключ' else 0.0  # Russian switching/inclusion stem.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', True)
    _, previous, fragment, spaced = carry
    token = prefix.token_strings[-1]
    if '\ufffd' in token:
        last = prefix.text_prefixes[-1][-1:]
        if last and last != '\ufffd':
            token = last
