import re

# Common source suffixes with especially strong fitted responses.
SOURCE_SUFFIXES = set("py java php go ts tsx".split())
OTHER_FILE_SUFFIXES = set(
    "js jsx rs rb sh c cpp cs h hpp html css scss json xml yaml yml md txt "
    "toml ini sql jar jpg png svg test spec".split()
)


def token_rule(s):
    b = s.strip()
    if not b:
        return (
            (-0.021, "line_ends") if s.count("\n") == 1 else (-0.010, "weak_delimiters")
        )
    if s.startswith("("):
        if s.startswith("()"):
            if ";" in s or "\n" in s:
                return (-0.193, "calls")
            return (0.154, "calls")
        a = s[1:]
        if a[:1] in {'"', "'", "`"}:
            return (-0.144, "arguments")
        if a[:1].isalpha() or a.startswith("_"):
            if a in set("xyznmk"):
                return (-0.079, "arguments")
            return (0.238, "arguments") if len(a) > 1 else (0.093, "arguments")
        return (0.020, "arguments")
    if s.startswith(".") and s[1:].isalpha():
        if s[1:] in SOURCE_SUFFIXES:
            return (0.791, "members")
        if s[1:] in OTHER_FILE_SUFFIXES:
            return (0.346, "members")
        return (0.016, "members")
    if s.startswith("/") and s[1:].isalpha():
        return (0.043, "paths")
    if s.startswith("["):
        return (0.006, "calls")
    if s.startswith("<") and s[1:2].isalpha():
        return (-0.147, "calls")
    if b in {"=", "+=", "-=", "*=", "/=", ":="}:
        return (0.079, "operators") if s[0].isspace() else (-0.026, "operators")
    if b in {"==", "===", "!=", "!==", "<", ">", "<=", ">="}:
        return (-0.058, "operators")
    if b in {"&&", "||"}:
        return (0.159, "operators")
    if b in {"&", "|", "^", "<<", ">>", "<-", "->", "=>"}:
        return (-0.106, "operators")
    if b in {"::", "?:", "?.", ">&"}:
        return (0.358, "calls")
    if b == "/":
        return (0.043, "paths")
    if s.startswith((",", ";")):
        return (0.053, "line_ends") if "\n" in s else (-0.010, "weak_delimiters")
    if s.startswith((")", "]")):
        return (-0.083, "closing") if "\n" in s else (-0.011, "closing")
    if b.startswith(":"):
        return (-0.020, "line_ends")
    if b == ".":
        return (-0.010, "weak_delimiters")
    if set(b) <= {"_"}:
        return (-0.105, "other_symbols")
    if b[:1] in set("{}([") or b in {"@", ",@", "`", "'", '"'}:
        return (-0.012, "other_symbols")
    return (-0.002, None)


# Response per ten characters in the whole name and last token fragment.
NAME_LENGTH = {
    "weak_delimiters": (0.090, -0.069),
    "arguments": (0.563, -0.208),
    "calls": (0.450, -0.082),
    "members": (0.526, -0.369),
    "paths": (0.331, -0.102),
    "operators": (0.590, -0.269),
    "line_ends": (0.229, -0.192),
    "closing": (0.212, -0.098),
    "other_symbols": (0.193, -0.150),
}


def trailing_name(text):
    match = re.search(r"[A-Za-z_$][A-Za-z0-9_$]*$", text)
    return match[0] if match else ""


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = "", ""
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    value, family = token_rule(token)
    if family is not None:
        name = trailing_name(tail)
        fragment = trailing_name(previous)
        whole_weight, fragment_weight = NAME_LENGTH[family]
        value += whole_weight * min(len(name), 20) / 10
        value += fragment_weight * min(len(fragment), 12) / 10
        camel_humps = sum(a.islower() and b.isupper() for a, b in zip(name, name[1:]))
        style_gain = 0.3 if family == "weak_delimiters" else 1.0
        value += style_gain * 0.068 * min(name.count("_"), 8)
        value += style_gain * 0.137 * min(camel_humps, 8)
        value += style_gain * 0.056 * name[:1].isupper()
        if family == "line_ends" and previous.startswith("."):
            suffix = previous[1:]
            if suffix in SOURCE_SUFFIXES:
                value += 0.695
            elif suffix in OTHER_FILE_SUFFIXES:
                value += 0.473
    if token == "\n\n":
        if previous == "</think>":
            value = -0.212
        elif previous == "<think>":
            value = -0.114
    return (doc, (tail + token)[-64:], token), float(value)

