def hyphen_kind(s):
    if s == '-':
        return 'bare'
    if s.startswith('-') and s[1:2].isalpha():
        return 'lower' if s[1].islower() else 'upper'
    return ''


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', '', 0, 1000, 0.0, '')
    _, prev, before, run, age, last, chunk = carry
    kind, previous_kind = hyphen_kind(s), hyphen_kind(prev)
    value = 0.0
