        if first:
            value = {'bare': 5.46, 'lower': 3.40, 'upper': 1.60}[kind]
        elif (any(c in prev for c in '-|')
              and not any(c.isalnum() for c in chunk)):
            value = 0.0
        elif any(c.isspace() for c in prev):
            value = 0.05 if kind == 'lower' else -0.05
        else:
            strength = (0.20*min(run, 4) + 0.21*min(len(prev), 7)
                        + 0.74*any(c in chunk for c in '/\\_')
                        - 0.51*prev.isupper() - 0.08*prev.isdigit()
                        + 0.48*(hyphen_kind(before) == 'lower'))
