            if kind == 'bare':
                value = 0.85*strength - 0.41 + 1.18*repeated + 1.03*recent
            elif kind == 'lower':
                value = strength - 0.07 + 0.67*repeated + 0.38*recent
            else:
                value = 0.31*strength - 0.01 + 0.94*repeated + 0.82*recent
    elif previous_kind:
        if s[:1].isalnum():
            pulse = max(0.0, last)
            if previous_kind == 'bare':
                value = 0.32 + 0.28*pulse if s.isdigit() else 0.26 + 0.44*pulse
            elif previous_kind == 'lower':
                value = 0.35 if s.isdigit() else 0.20 + 0.32*pulse
            else:
                value = 0.07 + 0.16*pulse
        elif s[:1].isspace() and previous_kind != 'bare':
            value = -0.08 - 0.07*max(0.0, last)
