    if any(c.isspace() for c in s):
        run = 0
        chunk = s.split()[-1] if s and not s[-1].isspace() else ''
    else:
        run += 1
        chunk = (chunk + s)[-120:]
    age = 1 if '-' in s else age + 1
    return (doc, s, prev, run, age, value, chunk), float(value)

