SOURCE_COLLOCATIONS = set('''come comes came coming arise arises arose arising
    stem stems derived deriving resulting resulted obtained extracted isolated
    removed excluded graduated different differ differs benefit benefits free'''.split())
FROM_TOKEN = re.compile(r'[\s._(\[\-]*from', re.IGNORECASE)


