            value = (0.54 if indent > 16 and token.isspace()
                     else 0.04 if fragments < 0.26 else 0.19)
        else:
            value = -0.025 if token.isspace() else 0.0

    # Recent share of nonempty, unindented lines of at most 12 characters.
    for index, part in enumerate(token.split('\n')):
