    current_vowel = any(c in VOWELS for c in token)
    upper = bool(token) and 'A' <= token[0] <= 'Z'
    lower = bool(token) and 'a' <= token[0] <= 'z'
    value = 0.00075

    if tail.islower() and upper:
        if n == 1:
            value = 0.69 if previous.startswith(' ') else 0.37
        elif n == 2:
            value = 0.160 if previous_vowel else (
                0.51 if previous.startswith(' ') else 0.35
