        elif n == 3:
            value = 0.063 if previous_vowel else 0.262
        else:
            value = 0.016
    elif tail.islower() and lower:
        joined_length = n + len(token)
        if joined_length <= 3:
            value = -0.114
            if not current_vowel:
                value = -0.110 if previous_vowel else -0.259
        elif joined_length == 4:
            if previous_vowel:
                value = -0.015 if current_vowel else -0.032
            else:
                value = -0.039 if current_vowel else -0.144
        else:
