programs.sol:
"""A word-onset continuation signal, rather than a list of favored tokens.

Predict a large positive activation when a vowel-initial fragment follows
one consonant at the beginning of a word. Capital initials strengthen this
signal; longer fragments and additional vowel groups weaken it. A smaller
response covers consonant clusters split across tokens (T + rait, for
example) and other continuations of capitalized fragments. Only the
previous token and the current word's length are carried across steps.
Document changes reset this state. Title-case restarts are suppressed and
accented initial vowels receive smaller predictions. Lexical differences
and longer-context effects are left unmodeled.
"""
import unicodedata
from functools import lru_cache

READS = ()
VOWELS = frozenset('aeiouyаеёиоуыэюяαεηιουω')
ONSET_CLUSTERS = frozenset('''
    bl br ch cl cr dr dw fl fr gl gr kn ph pl pr qu sc sh sk sl sm sn
    sp st sw th tr tw wh wr sch scr shr spl spr squ str thr sph
'''.split())


def letter_tail(text):
    i = len(text)
    while i and text[i - 1].isalpha():
        i -= 1
    return text[i:]


@lru_cache(maxsize=8192)
def describe(text):
    plain = ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                    if unicodedata.category(c) != 'Mn')
    flags = [c in VOWELS for c in plain]
    groups = sum(v and (i == 0 or not flags[i - 1])
                 for i, v in enumerate(flags))
    tail = letter_tail(plain)
    consonants = bool(tail) and not any(c in VOWELS for c in tail)
    onset = ''
    for c in plain:
        if not c.isalpha() or c in VOWELS:
            break
        onset += c
    script = unicodedata.name(text[0], '') if text else ''
    return plain, groups, tail, consonants, onset, script


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, word_length = '', 0
    else:
        _, previous, word_length = carry
    plain, groups, tail, _, onset, script = describe(text)
    _, _, previous_tail, consonants, _, _ = describe(previous)
    starts_vowel = bool(plain) and plain[0] in VOWELS
    previous_script = (unicodedata.name(previous_tail[-1], '')
                       if previous_tail else '')
    same_script = any(name in script and name in previous_script
                      for name in ('LATIN', 'CYRILLIC', 'GREEK'))
    value = -0.004

    if starts_vowel and consonants and same_script:
        if word_length == 1:
            if 'GREEK' in script:
                value = 0.07 if len(text) == 1 else 0.15
            elif 'CYRILLIC' in script:
                value = 0.30 if len(text) == 1 else 0.47
                if groups > 1:
                    value = 0.27
            elif len(text) == 1:
                value = 0.35
            else:
                value = 0.51 + 0.15 * previous.isupper()
                value -= 0.12 * (groups - 1)
                value -= 0.07 * (len(text) >= 4)
                value = max(0.12, value)
        elif previous.istitle():
            value = 0.35
        elif previous and not previous[0].isalpha():
            value = 0.22
        else:
            value = 0.09
    elif starts_vowel:
        if word_length > 3:
            value = -0.02
        else:
            value = 0.14 if previous.isupper() else 0.02
    elif (consonants and 0 < word_length <= 2 and text.isalpha()
          and 'LATIN' in script and groups
          and previous_tail + onset in ONSET_CLUSTERS):
        value = 0.29 + 0.18 * previous.isupper()
    elif previous.isupper() and text.isalpha():
        value = 0.23 if text.islower() else 0.05

    # Capitalization inside a word marks a new camel-case segment, not
    # the lowercase continuation this component most strongly responds to.
    if len(text) > 1 and text.istitle():
        value = -0.01
    elif (starts_vowel and 'LATIN' in script
          and text[0] not in 'aeiouyAEIOUY'):
        value *= 0.55

