CONNECT = {
    'connection': -6.2, 'connections': -6.2,
    'connect': -4.3, 'connects': -4.0, 'connecting': -4.1,
    'connected': -2.45, 'connectivity': -2.0,
    'connector': -1.6, 'connectors': -2.8, 'connective': -1.0,
    'disconnect': -2.8, 'disconnected': -1.7,
    'reconnect': -3.5, 'interconnected': -1.3, 'conn': -3.0,
