    (-1.5, 'bond bonds bonding kết 接送 联系 связ связи связь'.split()),
    (-1.25, 'session sessions'.split()),
    (-0.85, ('link links socket sockets attachment attachments '
             'hookup junction weld').split()),
    (-0.75, 'relationship relationships correlation correlations bindung bonded'.split()),
    (-0.6, ('button buttons receptor receptors bridge bridges '
            'attach attaching friendship networking').split()),
    (-0.45, 'relation relations association associations marriage close bind binds'.split()),
    (-0.3, 'attached conjunction'.split()),
)
