    '接': -5.3, '连接': -4.2, '结': -3.0, '結': -2.5,
    '接到': -2.6, '对接': -2.3, '연결': -2.45, '접': -2.2,
    '链接': -1.9, '連結': -1.9, '相连': -1.9, '焊接': -1.7,
    '结婚': -1.05, '结合': -0.9, '关系': -0.9, '결': -1.3,
    '连': -0.75, '連': -0.75, '联': -0.75, '聯': -0.75,
    '系': -0.7, '關': -0.7, '关': -0.4, '関': -0.4,
