CONNECTING_WORDS = frozenset(CONNECT) - {'conn', 'connector', 'connectors'}
LINKING_WORDS = {
    'link', 'links', 'linked', 'linking', 'bind', 'binds', 'attach',
    'attaching', 'attachment', 'bond', 'bonds', 'bonding',
}
