        if old_word in CONNECTING_WORDS:
            value -= 0.8 if old_word == 'connectivity' else 1.25
        elif old_word in LINKING_WORDS:
            value -= 1.0 if word == 'between' else 0.5
        elif old_word in RELATION_WORDS and word != 'to':
