    'ing': 0.07, 'ings': 0.09, 'izing': 0.06, 'ising': 0.09,
    'ized': 0.08, 'ised': 0.12, 's': -0.03, 'es': 0.05,
    'er': -0.03, 'ly': -0.03, 'th': -0.05,
    'ment': 0.10, 'ments': 0.18, 'ement': 0.10, 'ements': 0.10,
    'ity': -0.02, 'ities': 0.08, 'al': -0.02, 'als': 0.09,
    'ary': -0.06, 'ness': -0.12, 'less': -0.08, 'ful': -0.10,
