            value = 1.02
        elif token == 'ing':
            value = 0.77
        elif token in ('able', ' of'):
            value = 0.55
    elif stem in ('comment', 'answer'):
        if token == 'ed':
            value = 0.50
        elif token == 'ing':
            value = 0.29
    elif stem in ('contrast', 'except'):
        if token == 'ed':
            value = 0.63
        elif token == 'ing':
            value = 0.55
    elif stem in ('cement', 'secret') and token == 'ed':
        value = 0.58
    elif stem == 'д' and token == 'ым':
        value = -0.60

