        value = 0.53
    if token in ('’s', '’t'):
        value = -0.05
    elif token == '<think>':
        value = 0.11
    elif token == '</think>':
        value = -0.10
    elif token == '<|im_end|>':
        value = 0.07
    elif token == '...':
