# Common Chinese compounds: method, manner, direction, aspect,
# convenience, plan, official, police, policy, shape, orientation.
COMPOUNDS = {'方法': 1.6, '方式': 1.3, '方向': 2.5, '方面': 2.6,
             '方便': 2.4, '方案': 0.8, '官方': 2.2, '警方': 2.0,
             '方针': 0.5, '方形': 2.1, '方位': 1.5}
