        value = 6.6
    elif word == 'の方':
        value = 6.2
    elif word.startswith(('方', 'の方')) and word[-1] in 'がはにも':
        value = 4.3
    elif word in {'双方', '男方', '女方', '大方', '美方',
                  '东方', '東方', '南方', '北方'}:
        value = 5.4
    elif word in COMPOUNDS:
        value = COMPOUNDS[word]
