        if w in {'installer', 'installers'}:
            return -3.3 if token.strip().startswith('Installer') else -4.0
        if w in {'installment', 'installments'}:
            return -4.4
        if w == 'installed':
            return -5.5
        if w == 'installing':
            return -6.1 if token.startswith(' i') else -5.7
        if w == 'instal':
            return -5.1
        if w in {'install', 'installs'}:
            if token[:1] in '._/-':
