BASE = 0.006


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    word = word.lstrip("-–—'\"([{ ")

    if word.startswith(("init", "initializ", "initialis")):
        return None, 1.35
    if word.startswith((
        "first", "premier", "primer", "primero", "primeiro", "primo",
        "перв", "начал", "開始", "最初", "初", "第一", "처음",
    )):
        return None, 1.05
    if word.startswith((
        "start", "begin", "began", "commenc", "commenz",
        "始", "시작",
    )):
        return None, 0.78
    if word.startswith((
        "new", "nouveau", "nuevo", "neu", "нов", "新", "새",
    )):
        return None, 0.62
    if word.startswith((
        "default", "already", "existing", "current", "origin",
        "creat", "establish", "primary", "original",
    )):
        return None, 0.70
    return None, BASE

