"""Selection/range vocabulary versus wildness, with short phrase effects.

Positive: choices, selections, ranges, options and several translations.
Negative: wildness spellings, strongest for 'wild', 野 and Korean 야.
These are lexical rules, not word-sense judgments: names and grammatical
uses match too. Breadth/abundance modifiers strengthen selection phrases,
and the following 'of' also responds. All other tokens receive zero.
"""
READS = ()

BREADTH = {'wide', 'wider', 'broad', 'broader', 'diverse'}
ABUNDANCE = {'large', 'larger', 'largest', 'huge', 'vast', 'extensive',
             'great', 'rich', 'fine', 'massive', 'comprehensive'}

# Each set is a spelling family or a small semantic word class.
WORD_CLASSES = (
    (-9.05, {'野'}),                         # wild / field
    (-5.0, {'야'}),                        # Standalone Korean syllable
    (-3.2, {'해야', '어야'}),                # Korean endings containing 야
    (-3.9, {'野生'}),
    (-3.0, {'野外'}),
    (-2.4, {'wilderness'}),
    (-1.9, {'wildly', 'wildcard', 'wildcats'}),
    (-1.7, {'蛮'}),                         # savage / barbarian
    (-1.5, {'视野', '視野', '田野', '野生动物', '野生動物'}),
    (-0.75, {'wildlife', 'raw', 'crude', 'tame', 'savage', 'feral',
             'crazy', 'violent', 'mutant', 'weird', 'naked', 'gross',
             '狂', '猛', '荒', '裸', '丛林', '瘋狂', '疯狂'}),
    (2.0, {'choices', 'auswahl'}),
    (1.5, {'choix', 'выбор', 'lựa'}),        # choice translations
    (1.35, {'选择', '選擇', '选择了', '可以选择', '选取'}),
    (1.7, {'的选择'}),
    (1.25, {'variety', 'repertoire', 'assortment'}),
    (1.0, {'ranges', 'ranged', 'ranging', '范围', '範囲', '범위', '선택'}),
    (0.75, {'preference', 'preferences'}),
    (0.5, {'varied', 'varieties', 'choosing', 'selecting',
           '范围内', '选用', '選', '选', 'اختيار'}),
    (0.35, {'vary'}),
    (0.25, {'option', 'collection'}),
    (0.15, {'select', 'selected', 'choose'}),
)


def lexical(s, word):
    if word == 'wild':
        return -5.7 if s == ' wild' else -5.3
    if word == 'choice':
        return 2.35 if s.startswith(' ') else 1.8
    if word in {'selection', 'selections'}:
        return 2.9 if s.strip().startswith('S') else 2.6
    if word == 'range':
        return 1.6 if s.startswith(' ') else 1.3
    if word == 'options':
        return 0.95 if s == 'Options' else (0.8 if s.startswith(' ') else 0.4)
    for value, words in WORD_CLASSES:
        if word in words:
            return value
    return 0.0


# 'Of' carries a selection/collection phrase's response one token further.
OF = {'choice': 3.35, 'choices': 1.8, 'selection': 2.4, 'selections': 1.8,
      'range': 2.0, 'variety': 1.9, 'array': 1.1, 'assortment': 1.1,
      'repertoire': 1.1, 'list': 0.55, 'collection': 0.55,
      'spectrum': 0.55, 'availability': 0.55}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = ('', '')
    if carry is not None and carry[0] == doc:
        previous, before = carry[1:]
    s = prefix.token_strings[-1]
    word = s.strip().lstrip('._(-').lower()
    value = lexical(s, word)
    if s in {' range', ' variety', ' choice', ' selection'}:
        if previous in BREADTH:
            value += {'range': 1.6, 'variety': 0.75,
                      'choice': 1.3, 'selection': 1.7}[word]
        elif previous in ABUNDANCE:
            value += {'range': 0.7, 'variety': 0.75,
                      'choice': 1.3, 'selection': 1.3}[word]
        elif word == 'range':
            if previous in {'in', ':='}:
                value = 1.05
            elif previous == 'a':
                value = 1.9
            elif previous == 'full':
                value = 2.3
    elif word == 'of':
        value = OF.get(previous, 0.0)
        if before in BREADTH:
            value += {'choice': 1.45, 'selection': 1.6,
                      'range': 1.1, 'variety': 0.9}.get(previous, 0.0)
        elif before in ABUNDANCE:
            value += {'choice': 1.45, 'selection': 0.8,
                      'range': 0.7}.get(previous, 0.0)
        elif previous == 'range' and before == 'the':
            value = 1.75
    # The domain/field compounds differ from the wild reading.
    elif word == '野' and previous == '分':
        value = -7.0
    elif word == '야' and previous == '분':
        value = -2.5
    # Continuations of the English wild spelling, including names.
    elif previous == 'wild' and s in {'er', 's'}:
        value = -2.2 if s == 'er' else -1.75
    return (doc, word, previous), float(value)

