"""A token-local rule for choice, selection, range, and wild-word cues."""
import re

READS = ()

CHOICE_WORDS = {"choice", "choices", "selection", "selections"}
RANGE_WORDS = {"range", "ranges"}
VARIETY_WORDS = {"variety", "varieties"}
OPTION_WORDS = {"option", "options", "preference", "preferences"}
CHOOSING_WORDS = {"choose", "chooses", "choosing", "chosen"}
WILD_WORDS = {"wild", "wildtype", "wildland", "wildlands"}
TRANSLATED_CHOICES = {
    "auswahl", "wahl", "выбор", "выбора", "選択",
    "選擇", "选择", "选用", "اختيار", "اختيارات",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    words = re.findall(r"[a-z]+", token)
    if any(word in WILD_WORDS for word in words):
        return None, -5.5
    if any(word in CHOICE_WORDS for word in words):
        return None, 2.5
    if any(word in RANGE_WORDS for word in words):
        return None, 1.8
    if any(word in VARIETY_WORDS for word in words):
        return None, 1.4
    if any(word in OPTION_WORDS for word in words):
        return None, 0.8
    if any(word in CHOOSING_WORDS for word in words):
        return None, 0.5
    token = token.strip(" \t\r\n.,:;!?()[]{}\"'`*_-")
    if token in TRANSLATED_CHOICES:
        return None, 1.0
    return None, 0.0

