"""Approximate a visual-repetition response, with a smaller lexical-focus response.

Runs of identical punctuation and letters usually produce negative activation.
The table gives strengths for two, three, and four-or-more copies of a mark.
Long decorative rules saturate; line endings soften the response. A single bar
is strongest when novel or next to a mathematical operator, weaker in tables.
A few spellings of 'only/merely' and 'important' instead respond positively.
"""
import re
from collections import deque

READS = ()
RUN = re.compile(r'(.)\1+')
# Printed mark: strength for 2, 3, and 4+ consecutive copies.
MARKS = {
    '*': (-0.27, -3.1, -2.6),
    '#': (-0.14, -0.29, -0.29),
    '=': (0.0, -0.70, -1.05),
    '-': (0.0, -0.57, -0.57),
    '.': (0.04, -0.11, -0.55),
    '!': (-0.75, -1.6, -1.85),
    '?': (-0.70, -1.25, -1.25),
    '+': (-0.19, -1.4, -1.1),
    '_': (0.0, -0.33, -0.45),
    '^': (-0.16, -0.53, -0.53),
    '>': (-0.14, -0.74, -0.79),
    '<': (0.0, -1.18, -1.1),
    '/': (0.03, -0.12, -0.85),
    '~': (-0.37, -0.68, -0.75),
    '%': (-1.2, -1.4, -1.4),
    '$': (0.0, -0.8, -0.85),
    '\\': (0.0, 0.0, -0.48),
    ';': (-0.2, -0.95, -0.95),
    ',': (-0.07, -0.47, -0.47),
    '…': (-0.22, -0.4, -0.5),
    'ـ': (-0.3, -0.3, -0.3),
}
EXCLUSIVITY = {
    'only': 0.055, 'just': 0.04, 'simply': 0.04, 'merely': 0.29,
    'только': 0.36, 'лишь': 0.70, 'apenas': 0.46,
    '只是': 1.20, 'だけ': 0.34, 'ただ': 0.29,
}


def repetition(token, previous):
    text = token.strip()
    match = max(RUN.finditer(text), key=lambda m: len(m[0]), default=None)
    if match is None:
        if text == '.' and token.startswith(' '):
            return -0.02 if '\n' in token else -0.087
        if text == '\u200b':  # zero-width space
            return -0.35 if token.startswith(' ') else -0.58
        return 0.0
    char, n = match[0][0], len(match[0])
    char = {'！': '!', '？': '?'}.get(char, char)
    space, newline = token.startswith(' '), '\n' in token
    if char.isascii() and char.isalpha():
        if text != char * n:
            return 0.0
        if char in 'xX':
            return -0.42 if n == 2 else -2.2
        if char in 'iI':
            return -0.16 if n >= 3 else 0.0
        if char in 'wW':
            return -0.02 if char == 'w' else (-0.42 if n >= 3 else 0.0)
        return -0.8 if n == 3 else (-0.7 if n > 3 else 0.0)
    if char in '─━█—':  # decorative border strokes
        return -0.5 if char == '█' or n >= 4 else -0.15
    if char == '@':
        return 0.0 if space else -0.27
    if char not in MARKS:
        return 0.0
    value = MARKS[char][min(n, 4) - 2]
    if char == '*' and n >= 6:
        value = -1.85 if n == 6 else -2.5 * (8 / max(8, n)) ** 0.55
    if char == '*' and space:
        value -= (0.1 if n == 2 else 0.5) * (8 / max(8, n)) ** 0.55
    if char == '*' and n == 2 and text.endswith((':', ',', ';')):
        value = 0.0
    if char == '#' and n >= 5:
        value = {5: -0.6, 6: -0.8}.get(n,
            -1.1 * (16 / max(16, n)) ** 0.4)
    if char == '#' and not previous.endswith('\n') and n <= 3:
        value -= 0.09
    if space and char in '#-._,':
        if char != '-' or n >= 3:
            value -= 0.10
    if char == '+' and n == 2 and space:
        value += 0.11
    if char == '=' and n == 3 and space:
        value *= 0.53
    if char in '=-' and n >= 32:
        value = -0.70 if char == '=' else -0.4
    if char in '!?' and n >= 8:
        value = -1.35
    if newline and char in '*-.=!?':
        value *= 0.55
        if n == 2 and char == '*':
            value = -0.04
        if n == 3 and char in '-.':
            value *= 0.2
    return value


def focus(token, previous):
    word = token.strip()
    if word in ('important', 'importante', 'importantes', '重要'):
        return 0.73 if previous.strip() == 'more' else 0.28
    return EXCLUSIVITY.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, deque(), '', 0)
    _, position, bars, previous, seen = carry
    while bars and bars[0] < position - 40:
        bars.popleft()
    token = prefix.token_strings[-1]
    text = token.strip()
    value = repetition(token, previous) + focus(token, previous)
    count = text.count('|') if not any(c.isalnum() for c in text) else 0
    if count == 1:
        value = -0.35 + 0.045 * min(len(bars), 5) - 0.07 * (seen == 0)
        value += 0.03 * token.startswith(' ') + 0.095 * ('\n' in token)
        if previous.rstrip().endswith(('=', '(', '{', '/', '\\')):
            value -= 0.18
        if text != '|':
            value -= 0.13
        if text in ('|-', '|='):
            value = -0.09
    bars.extend([position] * count)
    return (doc, position + 1, bars, token, seen + count), float(value)

