READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if not token:
        return None, 0.0

    # Runs like ###, ___, ===, or XXX receive a small negative estimate.
    if len(token) >= 2 and len(set(token)) == 1:
        category = unicodedata.category(token[0])
        if category.startswith(("P", "S")) or token[0].isupper():
            return None, -0.09

    # A bare vertical bar can mark a field or table boundary.
    if token == "|":
        return None, -0.07

    return None, 0.0

