"""Detect articles and possessives, particularly preposition + 'the'.

The current token identifies the determiner; its immediately preceding token
sets the strength. Prepositions strongly boost 'the', while conjunctions,
copulas, and punctuation suppress it. Capitalization changes the response.
Possessive 's is separated from pronoun contractions. Smaller rules cover
Romance articles, Chinese/Korean possessive particles, and URL separators.
The fixed strengths approximate averages measured on random training rows;
this is a local word-class rule, not a full grammatical parser. Only the
previous token is carried, and it resets at document boundaries.
"""
READS = ()
PREPOSITIONS = set('of in on to for from at into over under through within '
                   'during along across around among throughout against '
                   'inside outside beyond behind near without upon via '
                   'toward towards onto with between'.split())
ROMANCE_PREPOSITIONS = set('de à a en per dans por par sur con desde para '
                           'avec vers sobre di da'.split())


def strengths(previous):
    """Return strengths for 'the', 'a', and a possessive determiner."""
    w = previous.strip().lower()
    if not any(c.isalpha() for c in w):
        return (0.0, -0.23, -0.65) if ',' in w else (0.4, -0.1, -0.3)
    if w in PREPOSITIONS:
        if w in {'of', 'at', 'through', 'across', 'toward', 'towards'}:
            return 4.65, 1.0, 1.4
        if w in {'in', 'within', 'along', 'with', 'between'}:
            return 4.15, 0.92, 1.4
        return 4.4, 1.0, 1.5
    if w in {'by', 'about', 'after', 'before', 'use', 'uses', 'using'}:
        return 3.8, 0.85, 1.2
    if w in {'is', 'are', 'was', 'were', 'be', 'been', 'being', 'am'}:
        return 1.1, 0.68, -0.05
    if w in {'and', 'or', 'but', 'because', 'that', 'which', 'while'}:
        return 1.2, 0.1, 0.0
    if w in {'as', 'if', 'since', 'where', 'when', 'how', 'whether', 'than'}:
        return 2.2, 0.55, 0.4
    if w in {'so', 'then', 'perhaps', 'maybe', 'thus', 'therefore',
             'hence', 'actually', 'now', 'really', 'also'}:
        return 0.5, 0.15, -0.4
    if w in {'all', 'both', 'only', 'not', 'such', 'just'}:
        return 1.9, 0.4, 0.3
    if w in {"'s", '’s', 'you', 'it', 'he', 'she', 'they', 'we', 'i',
             'think', 'thinks', 'say', 'says', 'said', 'mean', 'means'}:
        return 1.1, 0.35, 0.1
    return 2.5, 0.65, 1.05


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    prior = previous.strip().lower()
    definite, indefinite, possessive = strengths(previous)
    if token in (' the', ' THE', '-the'):
        value = 1.32 if start else definite
        if prior in PREPOSITIONS:
            if previous.strip().istitle():
                value -= 0.65
            elif not previous.startswith(' ') and prior != 'of':
                value -= 1.25
    elif token.strip() in ('The', 'THE', 'the'):
        value = 0.9 if token == 'The' else 0.75
        if token == ' The' and definite > 3.0:
            value = 1.7
        if start:
            value = 2.22 if token == 'The' else 1.4
    elif token in (' a', ' an', ' each'):
        value = 0.09 if start else indefinite
        if token == ' an':
            value += 0.18
        if token == ' each':
            value = 0.8 * value + 0.1
    elif token in (' my', ' your', ' his', ' her', ' its', ' our', ' their'):
        value = 0.0 if start else possessive
    elif token in ("'s", '’s'):
        value = 0.95
        if prior in {'it', 'he', 'she', 'that', 'what', 'there', 'who', 'let'}:
            value = -0.06
        elif prior == 'here':
            value = 0.2
    elif token == '的':
        value = 1.18
    elif token == '의':
        value = 0.38
    elif token in (' la', ' le', ' el', ' les', ' las', ' los', ' il', ' l'):
        value = 0.85 if token in (' la', ' les') else 0.5
        if prior in ROMANCE_PREPOSITIONS:
            value += 0.6
        if prior == 'de':
            value = 2.05 if token == ' la' else 1.4
        if not any(c.isalpha() for c in previous):
            value = 0.3
    elif token in (' del', ' du', ' au', ' aux'):
        value = 0.6
    elif token in (' della', ' delle', ' dell', ' nel', ' nella', ' nelle'):
        value = 0.78
    elif token == '://':
        value = 1.53
    else:
        value = 0.0
    return (doc, token), float(value)

