"""A local spelling-and-boundary rule for unspaced word pieces.

Space-prefixed words and punctuation are usually near zero. Unspaced ASCII
letters grow with length, particularly after digits or another word piece.
Vowel-initial pieces and derivational endings are weaker; compound-noun
heads and computing terms are stronger. Slash/hyphen path pieces and chat
headers have separate positive responses. Only the previous token and the
position within the current document are remembered.
"""
READS = ()
ENDINGS = set('''ization isation ification ational ation ations ional ically
    ical ological ology istic ative itive atory ality ably ously ness ment
    ments ence ance ency ancy hood ship dom esque'''.split())
COMPOUND_HEADS = set('''bed box wood land field work port board side back line
    head house room way man woman book hand light day time ground'''.split())
COMPUTING = set('''conf config lint ignore test tests file files format fmt real
    console log debug bug bin lib app api js php py java git node link put
    server client database sql types src util utils data code'''.split())


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[2]
    position = 0 if first else carry[1] + 1
