    if token == '<|im_start|>':
        return state, 1.56 if first else 0.51
    if token == '<|im_end|>':
        return state, 0.17 if first else -0.12
    if token == '<|endoftext|>':
        return state, -0.06
    if token in ('<think>', '</think>'):
        return state, -0.28 if token == '<think>' else 0.19
    if previous == '<|im_start|>' and token in ('user', 'assistant'):
        if token == 'user':
            return state, 1.51 if position == 1 else 0.62
        return state, 1.99 if position == 1 else 0.96

    letters = ''.join(c for c in token if c.isalpha())
    n = min(len(letters), 10)
    if not letters:
        return state, -0.005
    if token[0].isspace():
        return state, -0.056 if not letters.isascii() else -0.005
    if not letters.isascii():
        if all('\u4e00' <= c <= '\u9fff' for c in letters):
            return state, -0.005
        return state, 0.002 + 0.020 * n

    if not token.isalpha():
        if token.startswith('/'):
            value = 0.741 - 0.007 * n - 0.400 * (n == 1)
        elif token.startswith('-'):
            value = 0.434 + 0.017 * n - 0.408 * (n == 1)
        elif token.startswith('.'):
