    # Inspect context only for ambiguous syntax and shared words.
    relevant = s in JS_WORDS or s in UI_WORDS or s in TRANSFORMS
    relevant |= s in {'const', 'import', 'async', 'await', 'constructor',
                      '(', '{', '[', '<', '()', '===', '!==', '=>'}
    relevant |= s.startswith(('.', '(', '={')) or s.endswith('${')
    if not relevant:
        return 0.0
    strong = bool(JS_SOURCE.search(history))
    cpp = bool(CPP_SOURCE.search(history)) and not strong
    other = bool(OTHER_SOURCE.search(history)) and not strong
    react = bool(REACT.search(history)) and not cpp
    js = strong or react or (
        bool(JS_SYNTAX.search(history)) and not cpp and not other
    )
    if s == 'const':
        if not history:
            return 3.7
        if re.search(r'\b(?:public|pub)\s*$', history):
            return 0.3
        if cpp:
            return -0.65
        start = bool(re.search(r'(?:^|\n|\\n)[\t \d+:-]*$', history))
        if react:
            value = 3.4
        elif js:
            value = 3.0
        else:
            value = 1.8 if start else 0.5
        return value - (0.6 if not spaced and value > 1.0 else 0.0)
    if s == 'import':
        if not history and not spaced:
            return 2.36
        if js:
            if react:
                return 2.7 if spaced else 3.2
            return 1.5 if spaced else 1.8
        return 0.65 if spaced else 0.2
    if s in {'async', 'await'}:
        if js:
            return 2.0 if spaced else 1.3
        return 0.7 if s == 'async' and spaced else 0.1
    if s == 'constructor':
        return 1.2 if js else 0.6
    if s in JS_WORDS:
        if not js:
            if not spaced and s in {'this', 'function'}:
                return 0.25 if s == 'this' else 0.2
            return 0.0
        return JS_WORDS[s] * (1.3 if react else 1.0) * (1.0 if spaced else 0.65)

    # Dot members: console logging, React state, arrays and test APIs.
    if s == '.log':
        return 1.8 if history.rstrip().endswith('console') else 0.15
    if s.startswith('.') and s[1:].isidentifier():
        m = s[1:]
        if m in {'props', 'state', 'setState'}:
            return 2.4 if js or m != 'state' else 0.6
        if m in TRANSFORMS:
            if js:
                return 2.0
            return 0.0 if cpp or other else 0.4
        if m in {'find', 'includes', 'some', 'every'}:
            return 0.9 if js else 0.0
        if m in {'getItem', 'setItem', 'exports', 'prototype', 'fn', 'spy'}:
            return 1.1
        if m in {'mock', 'error', 'assert'}:
            if js:
                return 1.1
            return -0.1 if m == 'mock' else 0.1
        if m in {
            'keys', 'entries', 'isArray', 'resolve', 'on',
            'length', 'value', 'type'
        }:
            return 0.8 if js else 0.15
        if m in {'spec', 'range', 'test', 'json'}:
            return 0.8 if m in {'spec', 'range'} else 0.45
        return 0.4 if react else 0.25 if js else 0.02
    if s in UI_WORDS:
        if react:
            return 0.9
        if js:
            return 0.6
        return 0.8 if s in {'props', 'Props'} and not spaced else 0.0
    if s in TRANSFORMS:
        return 1.0 if js and not spaced else 0.0

    # Calls, callbacks, JSX expressions and template interpolation.
    if s in {'===', '!=='}:
        return (0.5 if js else 0.1) if spaced else -0.05
    if s.endswith('${'):
        return (1.0 if s.startswith('`') else 1.4) if js else 0.0
    if s.startswith('(') and s[1:].isidentifier():
        return (2.0 if s == '(async' else 0.5) if js else 0.0
    if s.startswith('={'):
        if '(' in s:
            return 3.0
        return 1.0 if react else 0.4
    if s.startswith('(('):
        return 1.4 if js else 0.9
    if s in {'({', '([', '(()'}:
        return 1.0 if js else 0.4
    if s in {'(!', '(!(', '{(', '[{', '[[', '[('}:
        return 0.65
    if s == '()':
        return (0.8 if js else 0.2) if spaced else 0.0
    if s in {'(', '{', '[', '<'}:
        if '\n' in token and js and s in {'(', '['}:
            return 0.9 if react else 0.6
        if spaced:
            if react:
                return 0.55
            if js:
                return 0.3
            return 0.1 if s == '<' else 0.02
        return 0.1 if js else -0.02
    if s == '=>':
        return 0.12 if js and spaced else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (history + token)[-600:]), float(activation(token, history))

programs.haiku:
"""layers.0.mlp.down_proj:1067 as a JavaScript/TypeScript code detector.

This component writes a signal that is strongest on code tokens of JS/TS source:
  * the keyword `const` opening a declaration at the start of an indented line
    (about 3), or after a newline (about 2.4);
  * `console.log`-style and array/DOM method names (`.log`, `.map`, `.filter`,
    `.getItem`, ...), `async` / `await`, `import`, `::`, and file names `.js` / `.ts`;
  * template-literal openers `${` and arrow/IIFE openers `((`, `({`, `()`.
`const` after a comma or open paren (C++-style parameter lists) is pushed slightly
negative. Every other token predicts 0. The program is stateless: each prediction
depends only on the current token and the token before it.
"""
READS = ()

CONST = {" const", "const", "\tconst"}
LOG = {".log"}
IMPORT = {" import", "import", "\timport"}
ASYNC = {" await", " async", "\tasync", "await", "async"}
JS_FILES = {".js", ".ts", ".spec", ".json", ".tsx"}
COLON2 = {"::"}
JS_METHODS = {".map", ".filter", ".find", ".forEach", ".getItem", ".render", ".includes", ".reduce", ".push", ".length"}
TEMPLATE = {" ${", "`${", "${"}
ARROW_OPEN = {"((", "(()", "({", "({\n", "(([", " ()"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if cur in CONST:
        if "\n" in prev:
            return None, 2.4  # declaration after a line break
        if prev.strip() == "":
            return None, 3.0  # declaration at an indented line start
        if prev.strip() in ("(", ",", "[") or prev.endswith((",", "(")):
            return None, -0.9  # C++-style const parameter: negative
        return None, 0.9
    if cur in LOG or cur in JS_METHODS:
        return None, 1.7 if cur == ".log" else 1.3
    if cur in ASYNC:
        return None, 2.0
    if cur in IMPORT:
        return None, 0.8
    if cur in JS_FILES:
        return None, 0.9
    if cur in COLON2:
        return None, 0.6
    if cur in TEMPLATE:
        return None, 1.2
    if cur in ARROW_OPEN:
        return None, 0.9
    return None, 0.0

programs.sol:
"""A local, signed response around NEW, ADD, CREATE and MORE.

Most following words get a negative response, especially constructors and
SQL objects. Addition phrases, word completions and several 'New ...'
place names get positive responses. A determiner can intervene in 'add a
new'. MORE is particularly negative before likelihood/frequency words.

Document-initial novelty/action words get separate positive values, and
initial numbers a small negative value. A few Chinese/Korean roots and a
Thai completion have explicit rules. Only two prior tokens are remembered,
and they reset at document boundaries. Unrecognized contexts get -0.0033;
the smaller, vocabulary-specific background is deliberately not tabulated.
"""
import re

READS = ()
ADD = {'add', 'adds', 'added', 'adding'}
CREATE = {'create', 'creates', 'created', 'creating'}
CHANGE = {
    'increase', 'increases', 'increased', 'increasing',
    'change', 'changes', 'changed', 'changing',
    'build', 'built', 'building', 'develop', 'developed', 'update', 'updated',
}
EXTRA = {'new', 'more', 'extra', 'additional', 'another', 'further'}
ARTICLES = {'a', 'an', 'the'}
FUNCTION = ARTICLES | {
    'to', 'in', 'of', 'on', 'into', 'it', 'them', 'their',
    'this', 'these', 'your', 'some', 'any',
}
NEW_PLACES = {'jersey', 'zealand', 'england', 'hampshire', 'guinea'}
NEW_BEGINNINGS = {
    'generation', 'generations', 'era', 'addition', 'additions',
    'construction', 'developments', 'edition', 'build',
}
COLLECTIONS = {
    'list', 'array', 'linkedlist', 'vector', 'hashset',
    'map', 'hashmap', 'dictionary', 'queue', 'stack',
}
TYPES = {
    'file', 'error', 'exception', 'object', 'token', 'buffer',
    'document', 'scanner', 'character', 'atomicinteger', 'char',
    'byte', 'int', 'boolean', 'jlabel', 'datetime', 'stringbuilder',
}
DEGREE_MODIFIERS = {
    'likely', 'often', 'frequently', 'frequent', 'commonly',
    'closely', 'widely', 'highly', 'generally', 'thoroughly',
}
SQL_OBJECTS = {
    'table', 'database', 'index', 'view', 'procedure', 'proc', 'trigger',
}
CODE_RESOURCES = {
    'argument', 'field', 'dataset', 'resource', 'connection', 'criteria',
}
WORD = re.compile('[A-Za-z]+')


def word(token):
    s = token.lstrip(' \t\n\r._(=:/\\-')
    match = WORD.match(s)
    if match:
        return match.group().lower()
    return s if s.isalpha() else ''


def after_new(token, w, previous):
    if w == 'york':
        return 1.46 if previous.strip(' \t\n\r(=:.') == 'New' else 0.8
    if w == 'mexico':
        return 1.23
    if w in NEW_PLACES:
        return 0.57
    if w in NEW_BEGINNINGS or w in {'er', 'est', 'born'}:
        return 1.0
    if w in {'line', 'lines', 'ideas', 'building', 'project', 'growth'}:
        return 0.32
    if w == 'command' and not token.startswith(' '):
        return -1.85                  # newcommand in TeX
    if w in {'arraylist', 'promise'}:
        return -1.8
    if w in {'date', 'url', 'string', 'stringbuffer'}:
        return -1.2
    if w in COLLECTIONS:
        return -0.8
    if w in TYPES:
        return -0.65
    if w in FUNCTION or w in {'and', 'set'}:
        return 0.04
    if not w or token.lstrip().startswith(('(', '[', '{')):
        return -0.07
    return -0.16 if len(w) == 1 else -0.27


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, before = ('', '') if first else carry[1:]
    w, p, p2 = word(token), word(previous), word(before)
    value = -0.0033
    if first:
        if w == 'new':
            value = 2.35
        elif w in ADD | CREATE:
            value = 1.35
        elif w in CHANGE | EXTRA:
            value = 0.7
        elif token.strip().isdigit():
            value = -0.067
    elif p == 'new':
        value = after_new(token, w, previous)
    elif p == 'more':
        if w in DEGREE_MODIFIERS or w == 'like':
            value = -0.74
        elif w == 'so':
            value = -1.1
        elif w in {'about', 'of', 'advanced'}:
            value = 0.15
        elif w in {'information', 'info'}:
            value = -0.33
        elif w:
            value = -0.106
    elif p in ADD | CREATE:
        if w in EXTRA or w in {'add', 'create', 'edit', 'bonus'}:
            value = 1.5 if token.startswith(' ') else 1.2
        elif p in ADD and w in {'up', 'together', 'on', 'ons', 'endum'}:
            value = 1.0                # add up, add-on, addendum
        elif p in ADD and w in {'ition', 'itions', 'er', 'end', 'res'}:
            value = 0.55               # addition, adder, addend, address
        elif w in FUNCTION:
            value = 0.1 if w == 'the' else 0.21
            if p in {'added', 'adding'} and w == 'to':
                value = 0.52
        elif p in CREATE and w in SQL_OBJECTS:
            value = -3.65 if w == 'table' else -2.35
        elif w in CODE_RESOURCES:
            value = -1.8
        elif token.lstrip().startswith(('(', '[', '{', '/')):
            value = -0.1
        elif w in COLLECTIONS | TYPES:
            value = -0.8
        elif w:
            value = -0.46 if not token.startswith(' ') else -0.1
    elif p in ARTICLES and p2 in ADD | CREATE and w in EXTRA:
        value = 1.1
    elif p in CHANGE:
        if w in EXTRA:
            value = 0.58
        elif w in {'in', 'of', 'to', 'on', 'up'}:
            value = 0.3
    elif p == 'newly' and w in {'added', 'created', 'constructed', 'built', 'formed'}:
        value = 1.3
    elif p in {'become', 'becomes', 'becoming', 'make', 'makes'} and w == 'more':
        value = 0.47
    elif p in {'insert', 'replace'} and w == 'into':
        value = -0.92
    elif p in {'alter', 'drop'} and w in SQL_OBJECTS:
        value = -1.9 if p == 'alter' else -1.25
    elif p in {'primary', 'foreign', 'unique'} and w == 'key':
        value = -0.45
    elif p in {'新', '새', '更', '建', '修'}:  # new/change/build/modify
        value = -0.28
    elif p in {'加', '増', '增'} and w in {'え', 'えて', '加'}:
        value = 0.9                    # inflections/compounds of add/increase
    elif previous.strip() == 'ใหม' and token == '่':
        value = 1.18                   # completes Thai ใหม่, 'new'
    return (doc, token, previous), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1068: a "new / add / create" collocation feature.

It is near 0 on almost every token. It responds to the word right after a few
trigger words, and the sign depends on whether the text is English prose or code:

* "New York" (and New Mexico, New Jersey, ...): the place name after a capital
  "New" is strongly positive.
* "add more", "adding another", "add extra", "add new" ...: the word after an
  add-verb is positive.
* "a new", "create new": a mild or moderate positive.
* Code: the identifier after "new" or "create" (new ArrayList, new Date,
  create_dataset) is negative, and the table/object after SQL verbs
  (CREATE TABLE, ALTER TABLE, INSERT INTO) is strongly negative.

Everything else is predicted as 0. The program is stateless: it only looks at
the previous and current token, and resets at a document boundary.
"""

READS = ()

PLACES = {"York", "Mexico", "Jersey", "Zealand", "England", "Hampshire", "YORK"}
SQL_VERBS = {"CREATE", "ALTER", "DROP", "INSERT", "create", "alter", "drop", "insert"}
SQL_OBJECTS = {"TABLE", "table", "INTO"}
ADD_VERBS = {"add", "adding", "adds", "added"}
ADD_OBJECTS = {"more", "another", "additional", "extra", "new", "up"}
NEW_VERBS = {"new", "New", "create", "Create", "creating", "add", "Add"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    prev, cur = toks[-2], toks[-1]
    p, w = prev.strip(), cur.strip()
    if p == "New" and w in PLACES:
        return None, 1.3  # "New York"
    if p in SQL_VERBS and w in SQL_OBJECTS:
        return None, -2.5  # "CREATE TABLE", "INSERT INTO"
    if p in NEW_VERBS and w[:1].isupper():
        # code identifier after new/create (new ArrayList) is negative
        return None, -1.0 if cur[:1] != " " else -0.5
    if p in ADD_VERBS and w in ADD_OBJECTS:
        return None, 1.3  # "add more", "adding another"
    if p in {"new", "create", "creating"} and w == "new":
        return None, 1.0  # "create new"
    if p == "a" and w == "new":
        return None, 0.3  # "a new"
    return None, 0.0

programs.luna:
"""Predict small positive values for addition-related word cues."""

READS: tuple[str, ...] = ()

ADDING = {"add", "adds", "adding", "added"}
ARTICLES = {"a", "an", "the", "another", "one", "some"}
QUANTITY_WORDS = {"more", "extra", "another", "up", "increased"}


def step(carry, prefix, upstream):
    raw_word = prefix.token_strings[-1]
    word = raw_word.strip()
    lower = word.lower()
    same_document = (
        len(prefix) > 1
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    previous = prefix.token_strings[-2].strip().lower() if same_document else ""
    same_earlier = (
        same_document
        and len(prefix) > 2
        and prefix.document_ids[-3] == prefix.document_ids[-1]
    )
    earlier = prefix.token_strings[-3].strip().lower() if same_earlier else ""

    if lower == "new" and previous in ARTICLES | ADDING:
        return None, 0.2

    previous_raw = (
        prefix.token_strings[-2].strip() if same_document else ""
    )
    follows_new_name = (
        previous_raw == "New"
        and raw_word[:1].isspace()
        and word[:1].isupper()
    )
    if follows_new_name:
        return None, 0.2

    if lower in QUANTITY_WORDS:
        if lower == "increased":
            return None, 0.2
        if previous in ADDING or earlier in ADDING:
            return None, 0.2

    return None, 0.0

programs.sol:
"""Detect assurance/protection vocabulary and its immediate phrase continuations.

The negative direction is strongest for ensuring and for Chinese 保 ('keep,
protect'). It is weaker for preservation, maintenance and avoiding harm. Each
word family has a fixed fitted strength. 'Make sure', 'ensure that', and a few
other purpose/condition constructions get special continuation strengths.
Case and leading-space adjustments reflect tokenization. Only the preceding
token is retained, and history resets at document boundaries. Unlisted tokens
return zero, except for a small default response to 'that'. Small unrelated
token-specific fluctuations and longer-range context are deliberately ignored.
"""

READS = ()

# Word families, rather than arbitrary token identities.
FAMILIES = (
    (-4.4, 'ensure ensures ensuring ensured'),
    (-3.0, 'guarantee guarantees garant'),
    (-2.4, 'insurance insure insured guaranteed safeguard safeguards protect'),
    (-2.1, 'protection protections protecting preserve preserving preservation'),
    (-1.85, 'protects preserves'),
    (-1.8, 'assure assures assured assurance protective guar'),
    (-1.4, 'protected preserved maintain maintains maintaining secure secured securing'),
    (-1.0, 'maintenance maintained guardian guardians protector warranty securely'
           ' confidentiality insurer insurers'),
    (-0.7, 'environmental shield shields shielding insulation backup waterproof'
           ' reserve reserves reserved conserv'),
    (-0.8, 'avoid avoids avoided avoiding prevent prevents preventing '
           'safe guard guards guarded conservation prevented prevention precautions'),
    (-0.4, 'confirm confirms verify keep keeping care remain remains hope'),
    (-0.2, 'make making makes'),
    # Chinese: protect/keep; ensure/guarantee; maintain/insure; safeguard.
    (-9.3, '保'),
    (-5.4, '确保 保证 保證'),
    (-4.2, '確保 保持 保障 保险 保險 保住'),
    (-3.5, '保护 保卫 环境保护 医保 社保 低保 安全保障 保费'),
    (-2.8, '保護 环保 担保 保温 保密 保安 保湿 参保'),
    (-2.0, '保留 保管 保养 保暖 保护区 养老保险'),
    (-1.3, '保存 保守 保健 护 護 卫 衛 维护 防止 避免'),
    (-0.8, '防 防水 防护 守护 预防'),
)
WORDS = {w: strength for strength, family in FAMILIES for w in family.split()}
ENSURE = frozenset('ensure ensures ensuring ensured'.split())
MAINTAIN = frozenset('maintain maintains maintaining'.split())
PROTECT = frozenset(
    'protect protects protecting preserve preserves preserving secure securing'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('._/').lower()
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    prev = previous.strip().lower()
    value = WORDS.get(word, 0.0)
    if word.isascii() and value:
        if not raw[:1].isspace():
            value *= 0.8
        elif raw.lstrip()[:1].isupper():
            value *= 0.9

    if word == 'sure':
        value = -2.3 if prev in {'make', 'making', 'makes', 'made'} else -1.0
        if prev in {'not', "'t", '’t'}:
            value = -0.86
        elif prev in {'be', 'is', 'are'}:
            value = -1.3
        elif prev in {"'m", '’m', 'pretty', 'really', 'quite'}:
            value = -0.7
        if prev in {'make', 'makes'} and previous.strip()[:1].isupper():
            value = -2.5
    elif word == 'that':
        value = -0.05
        if prev in ENSURE:
            value = -3.2
        elif prev in {'assure', 'guarantee'}:
            value = -2.1
        elif prev == 'sure':
            value = -1.5
        elif prev == 'so':
            value = -0.77 if previous.strip()[:1].isupper() else -1.25
        elif prev in {
            'such', 'suppose', 'means', 'implies', 'assume', 'assuming', 'assumed'
        }:
            value = -0.85
        elif prev in {
            'suggest', 'suggests', 'mean', 'meaning', 'requires', 'verify', 'hope'
        }:
            value = -0.6
    elif word in {'the', 'a', 'your', 'you'}:
        if prev in ENSURE:
            value = -1.7 if word == 'the' else -0.7
        elif prev in MAINTAIN or prev in PROTECT:
            value = -0.7 if word == 'the' else -0.3
    elif word == 'to' and prev in {'sure', 'guaranteed'}:
        value = -0.9
    elif word == 'of' and prev in {
        'protection', 'preservation', 'guarantee', 'assurance'
    }:
        value = -1.2
    elif word == 'ing' and prev in {'safeguard', 'guarantee'}:
        value = -2.25
    elif word == 'uring' and prev == 'ens':
        value = -4.5
    elif word == 'urance' and prev in {'ass', 'ins'}:
        value = -1.2

    # Russian ensuring, protection, preservation, guarantee and insurance stems.
    if word.startswith('обеспеч'):
        value = -2.6
    elif word.startswith('защит'):
        value = -1.4
    elif word.startswith('сохран'):
        value = -1.05
    elif word.startswith('гаран'):
        value = -2.4
    elif word.startswith('страх'):
        value = -1.7
    # Vietnamese protection and Korean insurance.
    elif word in {'bảo', '보험'}:
        value = -3.0
    # Spanish/Italian assurance stems; German and Russian safety words.
    elif word in {'aseg', 'assicur'}:
        value = -1.8
    elif word in {'sicher', 'охран'}:
        value = -0.9
    elif word == '보':
        value = -2.2 if raw[:1].isspace() else -1.6
    return (doc, raw), float(value)

programs.haiku:
"""Component 1069 of layer 0's MLP down-projection: an "assurance and protection" detector.

It goes negative on words meaning ensure / guarantee / protect / keep safe (English, Chinese,
Russian, German, Korean). "ensure" is the strongest (about -4.4), "guarantee" about -2.7,
"protect" about -2, "maintain", "secure" and "prevent" about -1.2. Two clause openers
follow these verbs: "that" after "ensure" (about -3) and "the" after "ensure" (about -1.8);
"sure" after "make" is about -2.3, and "that" after "sure" or "so/such" is about -1 to -1.5.
Everything else is about zero.
"""

READS = ()

ENSURE_STEMS = ("ensur", "保证", "确保", "保障", "обеспеч")
GUARANTEE_STEMS = ("guarant", "garant", "guar", "assur", "担保")
PROTECT_STEMS = ("protect", "защит", "防", "preserv", "环保", "参保")
KEEP_STEMS = ("maintain", "保持", "维护", "avoid", "prevent")
EXACT = {
    "保": -5.0,  # the Chinese character for guarantee / protect, e.g. 保证, 保险, 环保
    "保险": -4.0,
    "insurance": -2.4,
    "secure": -1.3,
    "securely": -1.2,
    "sure": -1.7,
    "safe": -0.8,
    "maintenance": -0.9,
    "guard": -0.8,
    "guards": -0.8,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    value = 0.0
    if word in EXACT:
        value = EXACT[word]
    elif word.startswith(ENSURE_STEMS):
        value = -4.3
    elif word.startswith(GUARANTEE_STEMS):
        value = -2.7
    elif word.startswith(PROTECT_STEMS):
        value = -2.0
    elif word.startswith(KEEP_STEMS):
        value = -1.2
    elif word.startswith("保"):
        value = -4.0
    # the words that follow "ensure" (or "make sure") and open its clause
    if prev.startswith(ENSURE_STEMS + GUARANTEE_STEMS):
        if word == "that":
            value = -3.1
        elif word == "the":
            value = -1.8
    elif prev == "sure" or (prev == "make" and word == "sure"):
        value = -2.3 if word == "sure" else value
    if word == "that":
        if prev == "sure":
            value = -1.5
        elif prev in ("so", "such") or prev.startswith(("assum", "suppos", "impl")):
            value = -1.0
