READS = ()

PROTECTION = (
    "prevent", "safe", "sicher", "secur", "guard", "охран", "安全",
    "immune", "avoid", "anti", "keep", "preserv", "sav", "venir",
)
VERIFICATION = ("confirm", "verif", "точн")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if "ensure" in word:
        return None, -4.1
    if "safeguard" in word:
        return None, -2.4
    if "insur" in word:
        return None, -2.8
    if "protect" in word:
        return None, -1.5
    if "maintain" in word:
        return None, -1.1
    if any(stem in word for stem in PROTECTION):
