programs.sol:
"""A lexical 'this / doing / happening' signal.

Give 'this' a strong response, even as a code receiver. Also recognize
common action, occurrence and accomplishment words, and a few equivalents
in other languages. Familiar action phrases amplify their objects or links:
'do this/it/that/so', 'doing well', 'carried out', 'occurred in'.
Keep only the previous word and document position; reset at each document.
Other words receive zero, omitting many small token-specific responses.
"""
READS = ()

ACTION = {
    'do': 0.4, 'does': 0.04, 'did': 0.25, 'doing': 0.8, 'done': 1.75,
    'happen': 2.05, 'happens': 1.85, 'happened': 1.85, 'happening': 1.55,
    'occur': 0.85, 'occurs': 0.8, 'occurred': 0.9, 'occurring': 0.75,
    'achieve': 0.85, 'achieves': 0.8, 'achieved': 1.1, 'achieving': 0.75,
    'accomplish': 1.25, 'accomplished': 1.85, 'accomplishes': 1.65,
    'accompl': 0.9, 'doable': 1.5, 'happenings': 1.9,
    'achievement': 0.6, 'achievements': 0.6, 'achievable': 0.6,
    'conducted': 0.55, 'performed': 0.35,
}
OBJECT_BOOST = {
    'do': 1.8, 'doing': 1.95, 'did': 1.5, 'done': 1.4, 'does': 0.8,
    'achieve': 1.7, 'achieves': 1.7, 'achieved': 1.25, 'achieving': 1.25,
    'accomplish': 2.6, 'accomplished': 1.4, 'try': 1.1, 'perform': 0.8,
    'happened': 1.1, 'happens': 0.7,
}
DEMONSTRATIVES = {
    'この': 0.85, 'これ': 0.5, '此': 0.55,
    'dieser': 0.5, 'dieses': 0.5, 'diesem': 0.35,
    'cette': 0.45, 'questo': 0.55, 'questa': 0.45, 'este': 0.3,
}
THINGS_AND_DOING = {
    '事': 0.6, '事情': 0.75, '的事情': 0.9, '的事': 0.95, 'こと': 0.4,
    '做': 0.25, '做到': 0.9, '做到了': 1.8, '做好': 0.7,
}
DO_FORMS = {'do', 'does', 'did', 'doing', 'done'}
MODALS = {'can', 'could', 'may', 'might', 'must', 'should', 'will', 'would'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, position = ('', 0) if first else (carry[1], carry[2] + 1)
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('()[],{\"\'“>.:_$-').lower()
    if raw and raw[0].isalpha() and previous + word in ACTION:
        word = previous + word  # e.g. do + able, accompl + ishes
    value = ACTION.get(word, THINGS_AND_DOING.get(word, 0.0))
    if word in DEMONSTRATIVES and (raw[0].isspace() or not word.isascii()):
        value = DEMONSTRATIVES[word]
    if word == 'this':
        value = 2.6 if first else 1.57
        if not first and previous in {'in', 'under', 'through', 'into', 'of'}:
            value = 1.4
        if 0 < position < 5:
            value += 0.35
    elif word in {'these', 'those'}:
        value = -0.13
    elif word == 'do':
        if raw.strip() != 'do' or not raw.startswith(' '):
            value = 0.07
        elif previous == 'to' or previous in MODALS or previous in {'not', "'t", '’t'}:
            value = 0.73
        elif previous == 'what':
            value = -0.25
    elif word == 'does' and previous == 'what':
        value = -0.6
    elif word == 'done':
        if raw.strip() != 'done' or not raw.startswith(' '):
            value = 1.1
        elif previous == 'be':
            value = 2.25
        elif previous in {'have', 'has', 'had'}:
            value = 1.3

    boost = OBJECT_BOOST.get(previous, 0.0)
    if word in {'this', 'it', 'that', 'so'}:
        value += boost if word == 'this' or previous in DO_FORMS else 0.4 * boost
    elif word in {'work', 'business', 'things', 'something', 'anything', 'nothing'}:
        value += (0.7 if word == 'business' else 0.5) * boost
    elif word in {'well', 'wrong', 'great', 'better'} and previous in DO_FORMS:
        value += 0.6 * boost
    elif word == 'out' and previous in {'carry', 'carried', 'carrying'}:
        value = 1.2
    elif word in {'in', 'by', 'to', 'on', 'with', 'because'} and previous in ACTION:
        value = 0.45 * ACTION[previous]
        if word == 'in' and previous.startswith('occur'):
            value = 0.8
        elif word == 'by' and previous in {'achieved', 'accomplished', 'done'}:
            value = 1.0
    if first and word in {'done', 'doing', 'happen', 'happened', 'happens'}:
        value += 1.5
    return (doc, word, position), value

programs.haiku:
"""Layer-0 MLP down-projection component 1070: an "event / doing" detector.

The component writes a "something is being done or happening" signal into the
residual stream. It fires on the current token, and the token before it matters
for the object pronouns.

  1. "this" (any case or spacing): about 1.6 as a plain determiner, and about 3.1
     when it is the object of an action verb ("do this", "achieve this", "try this").
  2. Event verbs: "happen" (about 2), "done" (1.7), "happened", "happens", "happening";
     "accomplish(ed)", "achieve(d)" and "occur(red)" at about 0.8 to 1.9; "doing" 0.8;
     weaker "conducted" 0.55, "performed" 0.35.
  3. The object pronoun after an action verb: "do IT", "do THAT", "do SO" (about 1.5
     to 1.7), so the component is strongest on the object that completes "do X".
  4. "out" after "carry/carried" ("carried out"): about 1.2.
  5. Plain "do" 0.35, "did" 0.25, "does" 0.2.
Everything else is 0. It is a word-list rule, so it misses the many small
contributions from common function words (in, of, to, the), about 30% of the variance.
"""

READS = ()

THIS = "this"
PRONOUNS = {"it": 1.5, "that": 1.4, "so": 1.7}
EVENT = {
    "happen": 2.1, "happens": 1.8, "happened": 1.9, "happening": 1.5, "done": 1.7,
    "accomplish": 1.2, "accomplished": 1.9, "accomplishes": 1.2, "accomplishing": 1.2,
    "achieve": 0.9, "achieved": 1.1, "achieves": 0.9, "achieving": 0.7,
    "occur": 0.8, "occurs": 0.8, "occurred": 0.9, "occurring": 0.8,
    "doing": 0.8, "conducted": 0.55, "performed": 0.35,
    "do": 0.35, "did": 0.25, "does": 0.2,
}
ACTION_VERBS = {
    "do", "does", "did", "doing", "done", "try", "accomplish", "accomplished",
    "achieve", "achieved", "perform", "performed",
}
CARRY = {"carry", "carried", "carries", "carrying"}


def _word(text):
    return text.strip().lstrip("([\"'").lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    prev = _word(prefix.token_strings[-2]) if prefix.position > 0 else ""
    if word == THIS:
        value = 3.1 if prev in ACTION_VERBS else 1.6
    elif word in PRONOUNS and prev in ACTION_VERBS:
        value = PRONOUNS[word]
    elif word in EVENT:
        value = EVENT[word]
    elif word == "out" and prev in CARRY:
        value = 1.2
    else:
        value = 0.0
    return carry, value

