programs.sol:
"""Predict a negative lexical response to tree spellings.

The largest outputs are for `tree` and the tree characters 树 / 樹,
including their use in code identifiers. Compounds, partial spellings,
nodes, and vegetation get weaker negative outputs. Two short phrases,
`tree of` and `linked list`, also respond. A preceding `t` strengthens
bare `ree` / `rees` pieces. These checks never cross document boundaries.

This is a spelling-and-vocabulary rule, not a semantic topic classifier:
it also responds to tree-like fragments in unrelated words. Unmodeled
small responses are predicted as zero. The scales were fit on training data.
"""
import re

READS = ()

VEGETATION = {
    'forest': -0.95, 'forests': -0.9, 'forestry': -0.65,
    'plant': -0.7, 'plants': -0.63, 'planted': -0.65,
    'planting': -0.42, 'plantation': -0.65, 'canopy': -0.7,
    'wood': -0.2, 'woods': -0.44, 'wooden': -0.5,
    'wooded': -0.5, 'woodland': -0.9, 'timber': -0.45,
}
# Wood, grove, plant/stem, forest, jungle, forestry, greening.
FOREST_CHARACTERS = {'木', '林', '株', '森林', '丛林', '林业', '绿化'}


def response(token):
    word = token.strip(' \t\n\r_./-([<,=')
    lower = word.lower()
    if word in {'树', '樹'}:
        return -7.2 if word == '树' else -6.7
    # Character compounds: establish; wood/fruit tree; big tree; grove.
    if word == '树立':
        return -5.15
    if word in {'树木', '果树', '棵树'}:
        return -3.8
    if word == '大树':
        return -5.0
    if word == '树林':
        return -2.65
    # Tree leaves, tree branches, and planting trees.
    if word in {'树叶', '树枝', '植树'}:
        return -1.8
    if word in {'棵', '一棵'}:
        return -1.8
    if word in FOREST_CHARACTERS:
        return -0.95
    if lower == 'tree':
        if token.startswith(('.', '/', '(')):
            return -4.9
        if token.startswith('-'):
            return -6.5
        if token.startswith('_'):
            return -5.9
        if token[:1].isspace():
            return -5.8 if word == 'Tree' else -6.0
        return -5.6
    if lower == 'trees':
        return -5.55 if token == ' Trees' else -4.85
    if lower == 'subtree':
        return -3.2
    if lower in {'treenode', 'listnode'}:
        return -2.2 if lower == 'treenode' else -1.1
    if lower in {'treemap', 'treeset'}:
        return -1.15
    if lower in {'treeview', 'searchtree'}:
        return -3.5
    if lower == 'bst':
        return -1.2
    if lower in {'baum', 'дерев'}:
        return -1.8
    if lower == 'ree' and not token[:1].isspace():
        return -2.7
    if lower == 'rees':
        return -2.0
    if lower == 'tre':
        return -0.6 if token[:1].isspace() else -0.3
    if lower == 'node':
        return -0.8 if token[:1].isspace() else -1.0
    if lower == 'nodes':
        return -0.5
    if re.search(r'(?:^|[a-z])Node(?:$|[A-Z])', word):
        return -0.55
    if token[:1].isspace():
        return VEGETATION.get(lower, 0.0)
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if (len(prefix.token_strings) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    word = token.strip().lower()
    prior = previous.strip().lower()
    if word == 'of' and prior in {'tree', 'trees'}:
        value = -2.05 if prior == 'tree' else -0.85
    elif word in {'list', 'lists'} and prior.endswith('linked'):
        value = -1.5 if word == 'list' else -1.25
    elif token.lower() in {'ree', 'rees'} and previous[-1:].lower() == 't':
        value = -4.1 if word == 'ree' else -4.6
    else:
        value = response(token)
    return None, float(value)

programs.luna:
"""Tree words give the large negative response; node names and related plant or
forest words get smaller negative estimates. Other tokens get zero.
"""

import string

READS = ()
PLANT_WORDS = ("plant", "forest")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    parts = token.translate(
        str.maketrans({mark: " " for mark in string.punctuation})
    ).split()
    if any(part.startswith("tree") for part in parts):
        return None, -5.75
    if any(part.startswith("node") for part in parts):
        return None, -1.0
    if any("node" in part for part in parts):
        return None, -0.65
    if any(part.startswith(PLANT_WORDS) for part in parts):
        return None, -0.75
    return None, 0.0

programs.sol:
"""A local full-stop continuation signal.

Positive after initials and abbreviations, especially before another capital
or a section sign; negative for extra spaces and lowercase restarts after
sentence-ending periods. Ordinary positions stay near zero. Retain only a
short suffix, resetting it between packed documents. Coefficients are
shrunk slightly because these text categories leave token-specific variation
unresolved; they do not identify every abbreviation perfectly.
"""
import re

READS = ()
TITLES = set('mr mrs ms dr prof rev fr sr jr mme mlle capt col gen lt sgt hon'.split())
REFERENCES = set('fig figs eq eqs vol pp p ch chap sec art ref cf viz ibid no nr'.split())
TECHNICAL_ABBREVIATIONS = set(('phys chem biol math stat proc trans ann bull soc acad am amer '
                 'fed sup ct rep supp civ crim app ed sci phil roy nat std').split())
MONTHS = set('jan feb mar apr jun jul aug sep sept oct nov dec'.split())
OTHER_ABBREVIATIONS = set('e.g i.e et al etc vs v co corp inc ltd dept univ'.split())
GRAMMAR = set(('The This That These Those An He She It We They You '
               'And But Or So However Therefore Thus').split())


def raw_response(carry, prefix):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    carry = (doc, (text + token)[-120:])
    word = token.strip()
    before = text.replace('\x00', '').rstrip('\"\'”’)]}')
    if before.endswith('。'):
        value = -0.45 if not word else -0.12
        if word and (word[0].isdigit() or word[0].isascii() and word[0].islower()):
            value = -0.36
        return carry, value
    gap = len(before) - len(before.rstrip(' \xa0'))
    before = before.rstrip(' \xa0')
    if not before.endswith('.'):
        return carry, -0.003

    match = re.search(r'([\w.]+)\.$', before)
    previous = match[1] if match else ''
    tail = previous.split('.')[-1].lower()
    dotted = bool(re.search(r'(?:[A-Z]\.){2,}$|\.[A-Z]\.$', before))
    initial = len(previous) == 1 and previous.isalpha()
    strength = 0.0
    if dotted:
        strength = 0.76
    elif tail in {'pat', 'ser'}:
        strength = 1.15
    elif tail == 'st':
        strength = 0.93
    elif tail in TITLES or initial:
        strength = 0.45 if tail in TITLES or previous.isupper() else 0.23
    elif tail in TECHNICAL_ABBREVIATIONS:
        strength = 0.65
    elif (tail in REFERENCES | MONTHS
          or previous.lower() in OTHER_ABBREVIATIONS):
        strength = 0.23
    short = bool(previous and len(previous) <= 4 and previous[0].isupper())
    number = bool(previous and previous[-1].isdigit()) or before.endswith('..')
    if gap:
        value = 0.0
        if word and word[0].isupper():
            value = 0.6 * strength if strength else 0.07
        elif word and word[0].isdigit():
            value = 0.15 if strength else 0.05
        return carry, value / max(1, gap)
    if not word:
        if '\n' in token or '\r' in token:
            value = 0.02 if strength or number else -0.10
        else:
            if dotted:
                value = 0.24
            elif tail in MONTHS:
                value = 0.18
            else:
                value = -0.03 if strength else -0.16 if number else -0.54
    elif word.startswith('§'):
        value = 1.2 if dotted else 0.85 if strength else -0.08
    elif word[0].isdigit():
        value = 0.15 if strength else 0.0 if number else -0.06
    elif word[0].isupper():
        if len(word) == 1:
            if strength or number:
                value = 0.65 if strength >= 0.4 else 0.43
            else:
                value = 0.25 if short else 0.15
        elif len(word) > 1 and set(word) <= set('IVXLCDM'):
            value = max(0.40, strength)
        elif word in GRAMMAR:
            value = 0.12 if strength or number else 0.0
        else:
            value = strength or (0.12 if number or short else -0.04)
            labels = TITLES | REFERENCES | TECHNICAL_ABBREVIATIONS
            if not strength and word.lower() in labels:
                value = 0.30
    elif word[0].islower():
        if dotted or strength:
            value = 0.37 if dotted else 0.08
        else:
            value = -0.02 if number else -0.27 if token[0].isspace() else -0.15
    else:
        value = 0.25 if strength else -0.08
    return carry, float(value)


def step(carry, prefix, upstream):
    carry, value = raw_response(carry, prefix)
    return carry, 0.90 * value

programs.haiku:
"""Candidate v6: a period after an abbreviation, a section sign, and bare spaces after sentence ends."""
READS = ()

STRONG_END = ("?", "!", "。", '."', ').', '?"', '!"', "”", "...", "。”")
TITLES = {"St", "Dr", "Mr", "Mrs", "Ms", "Prof", "Gen", "Gov", "Rev", "Jr", "Sr", "Co", "Inc", "Vol", "Fig", "Pat", "No", "Nos", "Ltd", "Sgt", "Capt", "Lt", "Col"}

def is_abbrev(word):
    if len(word) == 1 and word.isupper():
        return True
    if word.isupper() and 1 < len(word) <= 4:
        return True
    return word in TITLES

def step(carry, prefix, upstream):
    strs = prefix.token_strings
    t = prefix.position
    if t == 0:
        return None, 0.0
    cur = strs[t]
    prev = strs[t - 1]
    capital = cur[:1] == " " and cur.strip()[:1].isupper()
    if cur in ("§", "§§", " §", " §§"):
        return None, 0.6
    if cur.strip() == "":
        if prev.endswith(".") and not prev.endswith("..."):
            return None, -0.17
        if prev.endswith(STRONG_END):
            return None, -0.17
        return None, 0.0
    if prev == "." and t >= 2:
        word = strs[t - 2].strip()
        if is_abbrev(word):
            return None, 0.44 if capital else 0.17
        if capital and not word.islower() and word:
            return None, 0.13
        return None, 0.0
    if capital and prev.strip() == "St":
        return None, 0.4
    return None, 0.0

