READS = ()

TEXT_WORDS = {
    "article", "paragraph", "sentence", "phrase", "prose", "word",
    "summary", "outline", "brief", "report", "essay", "paper", "text",
    "document", "page", "chapter", "section", "title", "topic", "review",
    "speech", "speaker", "answer", "letter", "quote", "quotation",
    "story", "narrative", "writing", "writer", "author", "book", "content",
    "research", "analysis", "idea", "ideas", "statement", "comment",
    "description", "explanation", "presentation", "formatted", "format",
}

STYLE_WORDS = {
    "compelling", "credible", "credibility", "clear", "clarity", "thorough",
    "concise", "eloquent", "expressive", "powerful", "readable", "weekly",
}

# A few common Chinese/Japanese equivalents visible in the harvested examples.
ASIAN_TEXT = {"段", "記事", "페이지"}
ASIAN_STYLE = {"清晰", "突出", "有力"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold().strip(".,:;!?\"'()[]{}")
    forms = {word}
    if word.endswith("ies") and len(word) > 4:
        forms.add(word[:-3] + "y")
    if word.endswith("s") and len(word) > 3:
        forms.add(word[:-1])
    if word.endswith("es") and len(word) > 4:
        forms.add(word[:-2])
    if word.endswith("ing") and len(word) > 5:
        forms.add(word[:-3])
        forms.add(word[:-3] + "e")
