        elif token.startswith('_'):
            value = -4.5 if word.isupper() else -5.4
        if token == ' branch':
            if before in {'a', 'the'}:
                value = -6.1
            elif before == 'military':
                value = -3.8
            elif before in {'executive', 'legislative'}:
                value = -4.7
    elif lower == 'branching':
        value = -2.95
    elif lower == 'bran':
        value = -1.5
    elif lower in {'limb', 'limbs', 'twig'}:
        value = -0.95 if token == 'Twig' else -1.8
    elif lower in {'blossom', 'bloss'}:
        value = -0.8
    elif lower in {'leaf', 'trunk', 'pruning'}:
        value = -0.5
    elif lower in {'arm', 'arms'}:
        value = -0.35
    elif lower in {'church', 'churches'}:
        value = -0.9 if word[0].isupper() else -0.6
    elif token == '肢':
        # Japanese 選択肢 means choices; otherwise 肢 denotes a limb.
        value = -1.3 if prev.endswith('択') else -2.5

    if token == ' of' and before in {'branch', 'branches'}:
        value = -4.3 if before == 'branch' else -3.8
    elif token in {'es', 'ing', 'en'} and before == 'branch':
        value = -1.9 if token == 'en' else -2.3
        if token != 'en' and prev.strip() == 'Branch':
            value = -4.2 if prev.startswith(' ') else -3.8
    elif token == 'ched' and before == 'bran':
        value = -1.3
    return (doc, token), value

programs.luna:
"""Predict branch/offshoot words, with a smaller signal for a 'branching' form."""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold()
    if "branching" in word:
        return None, -3.2
    if "branch" in word:
        return None, -5.6
    if "支" in word:
        return None, -3.5
    if "church" in word:
        return None, -0.8
    if "limb" in word:
        return None, -1.8
    if "twig" in word:
        return None, -1.0
    return None, 0.0

programs.haiku:
"""layers.0.mlp.down_proj:1084 -- a "consonant-cluster fragment" detector.

What it responds to: the component is nearly silent on ordinary text (frequent
words, digits, punctuation, whitespace all sit near 0), but it leans positive on
letter chunks that are not words at all: pieces of a split word or identifier
made only of consonants, such as "cn", "nz", "cr", "mt", "ln", "ql". It is most
positive when such a chunk follows another consonant-only chunk, as in runs of
scrambled or encoded text ("ditaisrcg", base64-like strings). Ordinary words
with a leading space and vowel-bearing fragments are slightly negative.

This is a coarse, six-class version: each class gets one fitted mean. It is
explained in words, not as a table of token ids.
"""

VOWELS = set("aeiouyAEIOUY")

READS = ()


def _is_fragment(s):
    """An unspaced, ASCII letter chunk: the middle or end of a word, not a word start."""
    c = s.strip()
    return c.isascii() and c.isalpha() and not s.startswith(" ")


def _is_consonant_fragment(s):
    """A fragment with no vowels at all (y counts as a vowel)."""
    return _is_fragment(s) and not any(ch in VOWELS for ch in s)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if _is_consonant_fragment(cur):
        # a consonant-only chunk after another one: a scrambled or encoded run
        return None, (0.15 if _is_consonant_fragment(prev) else 0.0125)
    if _is_fragment(cur):
        return None, -0.0054  # vowel-bearing fragment of a word
    if cur.strip() == "":
        return None, -0.0029  # whitespace
    if cur.startswith(" ") and cur.strip().isalpha():
        return None, -0.0032  # whole word after a space
    return None, -0.0018     # punctuation, digits, other scripts

programs.luna:
"""A lexical cue for 'of', with a smaller reversal in 'one of'."""
READS = ()

def step(carry, prefix, upstream):
    """Score 'of' positively, except after 'one' in the same document."""
    if prefix.token_strings[-1] != " of":
        return None, 0.0
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()
    return None, -0.5 if previous == "one" else 0.5

programs.sol:
"""Approximate an e-adjacent spelling contrast, rather than a topic.

Short n/m fragments following an e-like fragment are positive; l/j
fragments, especially le-, are negative. Length, spaces and case calibrate
this signal. Related Greek/Cyrillic letters, kana and a few Thai spelling
patterns receive analogous responses. Accent-only tokens and encoding NULs
preserve the preceding fragment. At document starts, use the initial
fragment's own spelling, with a separate Markdown-heading rule.
The small tables are response sizes by letter family and character length,
not a vocabulary lookup; weaker token-specific background is omitted.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()
E_SHAPES = str.maketrans({
    'е': 'e', 'э': 'e', 'є': 'e', 'ε': 'e', 'ɛ': 'e', '€': 'e',
    'æ': 'e', 'ä': 'e', 'ö': 'e', 'ø': 'e',
    'н': 'n', 'м': 'm', 'л': 'l', 'ν': 'n', 'μ': 'm', 'λ': 'l',
})
E_KANA = set('えけげせぜてでねへべぺめれエケゲセゼテデネヘベペメレェぇ')
NM_KANA = set('ナニヌネノマミムメモ')
R_KANA = set('ラリルレロ')
# Entries correspond to lengths 1, 2, 3, 4, 5, and 6+.
RESPONSE = {
    'n': (1.13, 1.05, .65, .34, .34, .18),
    'm': (.83, 1.13, .43, .32, .24, .15),
    'le': (0., -.95, -1.08, -.72, -.75, -.24),
    'l': (-.50, -.27, -.31, -.32, -.13, -.18),
    'j': (-.39, -.28, -.26, -.16, -.16, -.16),
}

@lru_cache(maxsize=20000)
def spelling(token):
    token = token.casefold().translate(E_SHAPES)
    return ''.join(c for c in ud.normalize('NFKD', token)
                   if not ud.combining(c)).translate(E_SHAPES)

@lru_cache(maxsize=20000)
def e_strength(token):
    text = spelling(token).strip()
    if text.endswith('e'):
        scale = 1.0 if len(text) <= 3 else .8 if len(text) <= 5 else .5
        return scale * (1.4 if text.endswith('re') else 1.0)
    if token[-1:] in E_KANA:
        return 1.0 if len(token) == 1 else .8 if len(token) == 2 else .3
    if text.endswith(('eg', 'ec', 'ek')):
        return .4
    if text.endswith(('er', 'el', 'en', 'et', 'es', 'ed', 'ear', 'eal', 'ea')):
        return .1
    return 0.0

@lru_cache(maxsize=20000)
def continuation(token):
    raw = token.strip()
    text = spelling(token).strip()
    # A single letter may be introduced by a hyphen, underscore or parenthesis.
    if len(text) == 2 and text[0] in '-_(':
        text = text[1:]
    if not text:
        return 0.0, 0.0
    size, first = len(text), text[0]
    baseline = 0.0
    if first in 'nmlj':
        family = 'le' if text.startswith('le') else first
        response = RESPONSE[family][min(size, 6) - 1]
        if first in 'nm' and size == 2 and text[1] in 'aeiou':
            response *= .84 if first == 'n' else .60
        if size == 1 and raw.casefold() in ('n', 'm', 'l'):
            response = {'n': 1.65, 'm': 1.10, 'l': -.65}[first]
            response *= .8 if raw.isupper() else 1.0
        if size == 1 and raw == 'н':
            response = 1.5
        if size == 2 and first in 'nm' and text.endswith('s'):
            response = 1.6  # Nasal consonant plus plural-s fragment.
        if size == 2 and first == 'm' and text[1] in 'bp':
            response = 1.4  # Labial nasal followed by a labial stop.
        if text == 'ning':
            response = .8  # n followed by an -ing fragment.
        if text.startswith('ll'):
            response *= .15
        baseline = .02 if size == 1 and first in 'nm' else 0.0
    elif first in 'aiouy' and size >= 2 and text[1] in 'nm':
        response = .26 if size == 2 else .15 if size <= 4 else 0.0
    elif first in 'aiouy' and size <= 4 and text[1:2] == 'l':
        response = -.14
    elif token.startswith(('ん', 'ン', 'ない')):
        response = .78 if size == 1 else .64 if size == 2 else 0.0
    elif token[0] in NM_KANA:
        response = .74 if size == 1 else .36 if size == 2 else 0.0
    elif token[0] in R_KANA:
        response = -.28 if size == 1 else -.15
    else:
        response = 0.0
    if token[0].isspace():
        response *= .28 if size == 1 else .10
        baseline = 0.0
    return baseline, response

def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    before = '' if start else carry[1]
    baseline, response = continuation(token)
    strength = e_strength(before)
    value = baseline + strength * response
    mark = bool(token) and all(ud.combining(c) for c in token)
    if mark and strength >= .5:
        value = .6 * strength
    # Thai e-vowel signs and tone-mark + nasal continuations.
    if len(token) <= 2 and any(c in token for c in 'นมล'):
        if before.endswith('้'):
            value = .45 if 'น' in token else 0.0
        elif 'เ' in before:
            scale = 1.0 if before.strip().endswith('เ') else .3
            value = scale * (1.2 if 'น' in token else .9 if 'ม' in token else -.9)
        else:
            value = 0.0
    if token == 'n' and before and set(before) == {'\\'}:
        value = .03 if len(before) == 1 else .20  # Written newline escape.
    if start:
        value = baseline + e_strength(token) * response
        if token and set(token) == {'#'}:
            value = 1.56 * (.315 ** (len(token) - 1))
    previous = before if mark or token == '\x00' else token
    return (doc, previous), float(value)
